// Generated by tools/text-index.mjs (do not edit): every plain text line of the game and where it is said.
export const TEXT_INDEX = [{"text":"Ya pasaste mi examen. Colonia tiene más historia de la que cabe en una tarde.","uses":[{"file":"data/events.ts","line":70,"ctx":"ev_quiz","who":""}]},{"text":"Correcto.","uses":[{"file":"data/events.ts","line":81,"ctx":"ev_quiz","who":""}]},{"text":"No exactamente.","uses":[{"file":"data/events.ts","line":81,"ctx":"ev_quiz","who":""}]},{"text":"Ganaste el verso y yo perdí la voz. Pasa que la tradición manda.","uses":[{"file":"data/events.ts","line":98,"ctx":"ev_payada","who":""}]},{"text":"Cantás mejor que lo que decís. Llevate esto de recuerdo.","uses":[{"file":"data/events.ts","line":115,"ctx":"ev_payada","who":""}]},{"text":"Todavía te falta cancha, pero hay que animarse. Tomá un mate.","uses":[{"file":"data/events.ts","line":119,"ctx":"ev_payada","who":""}]},{"text":"El torneo del Club de Remo ya lo ganaste. Siempre hay otra regata, pero esa copa es tuya.","uses":[{"file":"data/events.ts","line":127,"ctx":"ev_torneo","who":""}]},{"text":"Torneo relámpago del Club de Remo: tres combates seguidos, sin curar entre uno y otro.","uses":[{"file":"data/events.ts","line":128,"ctx":"ev_torneo","who":""}]},{"text":"Si ganás los tres, te llevás una criatura del club como premio. Si perdés, podés volver a intentar.","uses":[{"file":"data/events.ts","line":128,"ctx":"ev_torneo","who":""}]},{"text":"Quedaste eliminado, pero atendimos a tus criaturas. Volvé cuando quieras.","uses":[{"file":"data/events.ts","line":142,"ctx":"ev_torneo","who":""}]},{"text":"¡Campeón del torneo relámpago!","uses":[{"file":"data/events.ts","line":147,"ctx":"ev_torneo","who":""}]},{"text":"El club te regala una criatura criada en la costanera.","uses":[{"file":"data/events.ts","line":147,"ctx":"ev_torneo","who":""}]},{"text":"Gracias por el trato. Lo cuido como si fuera mío.","uses":[{"file":"data/events.ts","line":158,"ctx":"ev_trueque","who":""}]},{"text":"Cuando tengas uno, volvé.","uses":[{"file":"data/events.ts","line":161,"ctx":"ev_trueque","who":""}]},{"text":"Gracias por ayudarme a cerrar esa historia. El mar guarda las otras.","uses":[{"file":"data/events.ts","line":175,"ctx":"ev_buscatesoros","who":""}]},{"text":"Dicen que un marinero escondió una caja cerca de la costa hace cien años.","uses":[{"file":"data/events.ts","line":177,"ctx":"ev_buscatesoros","who":""}]},{"text":"Los que saben algo andan por el pueblo. Todos recuerdan un pedacito distinto.","uses":[{"file":"data/events.ts","line":177,"ctx":"ev_buscatesoros","who":""}]},{"text":"Seguí preguntando por el pueblo.","uses":[{"file":"data/events.ts","line":178,"ctx":"ev_buscatesoros","who":""}]},{"text":"Un faro, tres palmeras y la sombra del mediodía… ¡Todo cuadra!","uses":[{"file":"data/events.ts","line":179,"ctx":"ev_buscatesoros","who":""}]},{"text":"¿Vamos a cavar juntos?","uses":[{"file":"data/events.ts","line":179,"ctx":"ev_buscatesoros","who":""}]},{"text":"Cavamos un buen rato. La caja estaba ahí, tal cual la describieron.","uses":[{"file":"data/events.ts","line":182,"ctx":"ev_buscatesoros","who":""}]},{"text":"El concurso de este año ya se juzgó. El parque queda para los paseos.","uses":[{"file":"data/events.ts","line":195,"ctx":"ev_concurso","who":""}]},{"text":"Tiempo cumplido. Vamos a juzgar lo que trajiste.","uses":[{"file":"data/events.ts","line":199,"ctx":"ev_concurso","who":""}]},{"text":"No atrapaste nada, así que no hay nada que juzgar. Gracias por participar.","uses":[{"file":"data/events.ts","line":202,"ctx":"ev_concurso","who":""}]},{"text":"Elegí la criatura que presentás. Es la que te quedás; las demás vuelven al parque.","uses":[{"file":"data/events.ts","line":205,"ctx":"ev_concurso","who":""}]},{"text":"Resultados:","uses":[{"file":"data/events.ts","line":213,"ctx":"ev_concurso","who":""},{"file":"data/events.ts","line":297,"ctx":"ev_pesca","who":""}]},{"text":"¡Primer puesto!","uses":[{"file":"data/events.ts","line":217,"ctx":"ev_concurso","who":""}]},{"text":"Segundo puesto. Muy bien.","uses":[{"file":"data/events.ts","line":218,"ctx":"ev_concurso","who":""}]},{"text":"Tercer puesto.","uses":[{"file":"data/events.ts","line":219,"ctx":"ev_concurso","who":""}]},{"text":"Quedaste cuarto, pero participar suma. Una compensación.","uses":[{"file":"data/events.ts","line":220,"ctx":"ev_concurso","who":""}]},{"text":"Concurso de captura del Parque de Canelones: una sola participación.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Te damos 20 balls del parque y 8 minutos. Atrapá criaturas dentro del parque; al final elegís una y los jueces la puntúan.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Se puntúa el nivel, lo rara que es, sus características y cuánta salud conserva al atraparla.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Suerte. Cuando suene la campana, volvé a verme.","uses":[{"file":"data/events.ts","line":229,"ctx":"ev_concurso","who":""}]},{"text":"Te acompaño a la salida.","uses":[{"file":"data/events.ts","line":235,"ctx":"ev_concurso_salida","who":"Guardaparque"}]},{"text":"Ya me ganaste mis tres acertijos. Se me acabaron los buenos.","uses":[{"file":"data/events.ts","line":245,"ctx":"ev_adivino","who":""}]},{"text":"Hago tres preguntas y no perdono ninguna.","uses":[{"file":"data/events.ts","line":246,"ctx":"ev_adivino","who":""}]},{"text":"Si respondés bien las tres seguidas, hay premio. Si fallás una, empezamos de nuevo.","uses":[{"file":"data/events.ts","line":246,"ctx":"ev_adivino","who":""}]},{"text":"No es eso. Pensalo mejor y volvé a empezar.","uses":[{"file":"data/events.ts","line":254,"ctx":"ev_adivino","who":""}]},{"text":"Las tres. Hacía años que nadie me ganaba.","uses":[{"file":"data/events.ts","line":259,"ctx":"ev_adivino","who":""}]},{"text":"El concurso de este año ya tiene ganador: vos. Gracias por participar.","uses":[{"file":"data/events.ts","line":268,"ctx":"ev_pesca","who":""}]},{"text":"Concurso de pesca del río. Hace falta una caña para anotarse. El pescador de la playa regala una vieja.","uses":[{"file":"data/events.ts","line":271,"ctx":"ev_pesca","who":""}]},{"text":"Concurso de pesca del Uruguay: una sola participación, 5 minutos de reloj.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Pescá desde el muelle: parate frente al agua y apretá A. Cada pez que saques queda registrado.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Al final, o cuando quieras entregar, volvé conmigo y elegí el mejor. Se puntúa nivel, rareza, características y estado.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Lo que saques depende de tu caña: la vieja solo trae lo más común.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"¡Empieza el reloj! Pescá todo lo que puedas.","uses":[{"file":"data/events.ts","line":276,"ctx":"ev_pesca","who":""}]},{"text":"¡Tiempo! Veamos qué sacaste.","uses":[{"file":"data/events.ts","line":283,"ctx":"ev_pesca","who":""}]},{"text":"No sacaste nada, así que no hay nada que juzgar. Podés anotarte otra vez cuando quieras.","uses":[{"file":"data/events.ts","line":286,"ctx":"ev_pesca","who":""}]},{"text":"Elegí el pez que presentás. Es el que te quedás; los demás vuelven al río.","uses":[{"file":"data/events.ts","line":289,"ctx":"ev_pesca","who":""}]},{"text":"La carrera ya la ganaste. El récord de la ciclovía sigue siendo tuyo.","uses":[{"file":"data/events.ts","line":314,"ctx":"ev_carrera_juez","who":""}]},{"text":"Esto es una carrera de bicicletas. Sin bici no se larga.","uses":[{"file":"data/events.ts","line":315,"ctx":"ev_carrera_juez","who":""}]},{"text":"Se te fue el tiempo. El límite es de 24 segundos. Podés largar de nuevo cuando quieras.","uses":[{"file":"data/events.ts","line":320,"ctx":"ev_carrera_juez","who":""}]},{"text":"Es un tiempo de campeonato. Medalla de oro.","uses":[{"file":"data/events.ts","line":323,"ctx":"ev_carrera_juez","who":""}]},{"text":"Muy buen tiempo. Medalla de plata.","uses":[{"file":"data/events.ts","line":324,"ctx":"ev_carrera_juez","who":""}]},{"text":"Llegaste dentro del límite. Medalla de bronce.","uses":[{"file":"data/events.ts","line":325,"ctx":"ev_carrera_juez","who":""}]},{"text":"Carrera de ida y vuelta por la Ciclovía: hasta el cronometrista del final y de regreso acá.","uses":[{"file":"data/events.ts","line":328,"ctx":"ev_carrera_juez","who":""}]},{"text":"El límite son 24 segundos. Los ciclistas del camino tienen que haber quedado atrás: si te cruzan, te frenan.","uses":[{"file":"data/events.ts","line":328,"ctx":"ev_carrera_juez","who":""}]},{"text":"Preparados… ¡Ya!","uses":[{"file":"data/events.ts","line":331,"ctx":"ev_carrera_juez","who":""}]},{"text":"Qué carrera. Todavía se comenta.","uses":[{"file":"data/events.ts","line":336,"ctx":"ev_carrera_meta","who":""}]},{"text":"Acá termina la Ciclovía. El que organiza las carreras está en la largada, al sur.","uses":[{"file":"data/events.ts","line":337,"ctx":"ev_carrera_meta","who":""}]},{"text":"Llegaste tarde: ya pasó el tiempo límite. Volvé a largar desde el sur.","uses":[{"file":"data/events.ts","line":339,"ctx":"ev_carrera_meta","who":""}]},{"text":"Mi abuelo contaba que la caja del marinero estaba a la vista del faro, pero que nadie la vio nunca de día.","uses":[{"file":"data/events.ts","line":359,"ctx":"Persona (Pescador, aspecto sailor, evento ev_pista)","who":"Pescador"}]},{"text":"Tres palmeras había en la punta, decía mi madre. Hoy queda solo una, la más chica.","uses":[{"file":"data/events.ts","line":360,"ctx":"Persona (Abuela del almacén, aspecto oldman, evento ev_pista)","who":"Abuela del almacén"}]},{"text":"A mediodía la sombra de la palmera señala hacia el mar. Mi tío dice que ahí hay que cavar.","uses":[{"file":"data/events.ts","line":361,"ctx":"Persona (Nene, aspecto nino, evento ev_pista)","who":"Nene"}]},{"text":"Desde chico pesco bajo ese muelle. El río tiene humor propio.","uses":[{"file":"data/fraybentos.ts","line":11,"ctx":"Persona (Pescador, aspecto sailor)","who":"Pescador"}]},{"text":"Hoy no vi a la gente de la boletería. Los del barco andan nerviosos y nadie me explica por qué.","uses":[{"file":"data/fraybentos.ts","line":11,"ctx":"Persona (Pescador, aspecto sailor)","who":"Pescador"}]},{"text":"Trabajé treinta años en esa planta. Las cámaras de frío tenían cintas por todos lados: una te llevaba, otra te devolvía.","uses":[{"file":"data/fraybentos.ts","line":13,"ctx":"Persona (Jubilado del Anglo, aspecto obrero)","who":"Jubilado del Anglo"}]},{"text":"Si entrás, no te enojes con las cintas. Cada una va para un solo lado, y se aprende probando.","uses":[{"file":"data/fraybentos.ts","line":13,"ctx":"Persona (Jubilado del Anglo, aspecto obrero)","who":"Jubilado del Anglo"}]},{"text":"Junto latas viejas del Anglo. Dicen que algunas valen plata.","uses":[{"file":"data/fraybentos.ts","line":15,"ctx":"Persona (Nene, aspecto nino)","who":"Nene"}]},{"text":"Una vez encontré una con el dibujo de un barco. ¿Será el mismo de la boletería?","uses":[{"file":"data/fraybentos.ts","line":15,"ctx":"Persona (Nene, aspecto nino)","who":"Nene"}]},{"text":"Traigo carga de Young. Desde que cerraron la salida norte con el zarzal, tengo que dar la vuelta por la ruta.","uses":[{"file":"data/fraybentos.ts","line":17,"ctx":"Persona (Camionero, aspecto camionero)","who":"Camionero"}]},{"text":"Alguien con una herramienta filosa lo arreglaría en un minuto.","uses":[{"file":"data/fraybentos.ts","line":17,"ctx":"Persona (Camionero, aspecto camionero)","who":"Camionero"}]},{"text":"Un camino de tierra sube hacia el norte.","uses":[{"file":"data/maps-act2.ts","line":168,"ctx":"Persona","who":""}]},{"text":"Antes de seguir, hay que resolver lo de la fábrica de Minas: el Equipo PP sigue activo.","uses":[{"file":"data/maps-act2.ts","line":168,"ctx":"Persona","who":""}]},{"text":"Al norte empieza la Ciclovía, un camino pavimentado larguísimo.","uses":[{"file":"data/maps-act2.ts","line":207,"ctx":"Persona","who":""}]},{"text":"Un cartel dice: \"Solo bicicletas\".","uses":[{"file":"data/maps-act2.ts","line":207,"ctx":"Persona","who":""}]},{"text":"El camino al este lleva a Rivera.","uses":[{"file":"data/maps-act2.ts","line":208,"ctx":"Persona","who":""}]},{"text":"Un guardia te frena: \"Sólo pasan entrenadores con la Medalla Tacuarembó\".","uses":[{"file":"data/maps-act2.ts","line":208,"ctx":"Persona","who":""}]},{"text":"El camino al oeste baja hacia Salto.","uses":[{"file":"data/maps-act2.ts","line":209,"ctx":"Persona","who":""}]},{"text":"Un guardia te frena: \"La Ruta 31 está cerrada. Primero resolvé lo de Rivera\".","uses":[{"file":"data/maps-act2.ts","line":209,"ctx":"Persona","who":""}]},{"text":"Un camino sigue hacia el sur, a Paysandú.","uses":[{"file":"data/maps-act2.ts","line":299,"ctx":"Persona","who":""}]},{"text":"Pero la Represa sigue en manos de la gente de gris, y el camino se abre recién cuando tengas la Medalla Salto y haya luz.","uses":[{"file":"data/maps-act2.ts","line":299,"ctx":"Persona","who":""}]},{"text":"El frigorífico es propiedad privada.","uses":[{"file":"data/maps-act2.ts","line":378,"ctx":"Persona (aspecto grunt)","who":""}]},{"text":"La puerta del camarote 2 está cerrada con llave.","uses":[{"file":"data/maps-act2.ts","line":445,"ctx":"Persona","who":""}]},{"text":"La puerta de la bodega tiene un candado grande. Hace falta la llave.","uses":[{"file":"data/maps-act2.ts","line":446,"ctx":"Persona","who":""}]},{"text":"La puerta a la cubierta superior está con llave. Solo la tripulación tiene una.","uses":[{"file":"data/maps-act2.ts","line":462,"ctx":"Persona","who":""}]},{"text":"Boletería del Buquebus \"China Zorrilla\".","uses":[{"file":"data/maps-act2.ts","line":617,"ctx":"Persona (Boletería, aspecto clerk)","who":"Boletería"}]},{"text":"El empleado que despacha los pasajes no vino hoy. Dicen que quedó trabajando en el frigorífico, y no lo dejan salir.","uses":[{"file":"data/maps-act2.ts","line":617,"ctx":"Persona (Boletería, aspecto clerk)","who":"Boletería"}]},{"text":"La Liga de Uruguay: cuatro miembros del Alto Mando y el Campeón.","uses":[{"file":"data/maps-act2.ts","line":763,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"No podés volver atrás una vez que empezás.","uses":[{"file":"data/maps-act2.ts","line":763,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"¡Esperá, {player}!","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"Afuera del pueblo hay criaturas salvajes en los pastizales.","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"No podés irte sin hablar con el Maestro Tabárez. Pasá primero por su laboratorio.","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"Los turistas vienen desde Buenos Aires en lancha, a ver los astilleros.","uses":[{"file":"data/maps.ts","line":44,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Dicen que en las noches de niebla el río se ve más ancho que el mar.","uses":[{"file":"data/maps.ts","line":44,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Cuando yo era joven, había Ceibos en todas las orillas.","uses":[{"file":"data/maps.ts","line":45,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Ahora casi solo los cuida el Maestro Tabárez.","uses":[{"file":"data/maps.ts","line":45,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"¿Vas al laboratorio? Hoy entregan criaturas.","uses":[{"file":"data/maps.ts","line":46,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Buen compañero te tocó. Cuidalo.","uses":[{"file":"data/maps.ts","line":47,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Si se debilita, pasá por tu casa: tu madre siempre tiene el mate listo.","uses":[{"file":"data/maps.ts","line":47,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Buen día.","uses":[{"file":"data/maps.ts","line":82,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Si tus criaturas están debilitadas, en Montevideo está la Policlínica. Las atienden gratis.","uses":[{"file":"data/maps.ts","line":82,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"El Estadio Centenario está cerrado.","uses":[{"file":"data/maps.ts","line":126,"ctx":"Persona","who":""}]},{"text":"Solo entran quienes tengan las 12 medallas y hayan detenido al Dr. Díaz, el fundador del Equipo PP.","uses":[{"file":"data/maps.ts","line":126,"ctx":"Persona","who":""}]},{"text":"En la Rambla, la gente toma mate y mira el río.","uses":[{"file":"data/maps.ts","line":138,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"El Río de la Plata es marrón por los sedimentos, aunque parezca un mar.","uses":[{"file":"data/maps.ts","line":138,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"El gimnasio de Montevideo es el Palacio de la Luz, la sede de UTE.","uses":[{"file":"data/maps.ts","line":139,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La presidenta, Sofía, usa criaturas de tipo Eléctrico. Las de Tierra no reciben su electricidad.","uses":[{"file":"data/maps.ts","line":139,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La terminal del Buquebus está cerrada por reformas.","uses":[{"file":"data/maps.ts","line":140,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"Los barcos a Buenos Aires salen desde Colonia del Sacramento.","uses":[{"file":"data/maps.ts","line":140,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"El Palacio Salvo fue el edificio más alto de Sudamérica.","uses":[{"file":"data/maps.ts","line":141,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Adentro trabaja gente que sabe mucho de criaturas.","uses":[{"file":"data/maps.ts","line":141,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Esa niebla no es natural. Unos hombres de gris la generan con máquinas.","uses":[{"file":"data/maps.ts","line":177,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Se hacen llamar Equipo PP.","uses":[{"file":"data/maps.ts","line":177,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La Mano es una escultura de dedos que emergen de la arena.","uses":[{"file":"data/maps.ts","line":211,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Es un recordatorio para los bañistas: la playa Brava es peligrosa.","uses":[{"file":"data/maps.ts","line":211,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Desde el puerto se ve la Isla de Lobos.","uses":[{"file":"data/maps.ts","line":212,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"A veces, en invierno, aparece una ballena cuyo canto se oye desde la costa.","uses":[{"file":"data/maps.ts","line":212,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"Con este calor, lo que más apetece es un chivito en la playa.","uses":[{"file":"data/maps.ts","line":213,"ctx":"Persona (aspecto swimmer)","who":""}]},{"text":"El gimnasio de acá es la planta potabilizadora de OSE. Su presidenta, Lucía, usa tipo Agua.","uses":[{"file":"data/maps.ts","line":215,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Planta y Eléctrico le hacen daño.","uses":[{"file":"data/maps.ts","line":215,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Un canto profundo sale del agua.","uses":[{"file":"data/maps.ts","line":218,"ctx":"Persona","who":""}]},{"text":"El Equipo PP se llevó la lámpara del faro.","uses":[{"file":"data/maps.ts","line":248,"ctx":"Persona (aspecto keeper)","who":""}]},{"text":"Sin luz, los barcos pueden chocar contra las rocas.","uses":[{"file":"data/maps.ts","line":248,"ctx":"Persona (aspecto keeper)","who":""}]},{"text":"Acá no hay red eléctrica ni calles asfaltadas.","uses":[{"file":"data/maps.ts","line":252,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Los lobos marinos descansan al sol sobre las rocas.","uses":[{"file":"data/maps.ts","line":252,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Las dunas se mueven con el viento. El pueblo entero cambia cada año.","uses":[{"file":"data/maps.ts","line":253,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Cuando sopla el pampero, el cielo queda despejado.","uses":[{"file":"data/maps.ts","line":292,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Dicen que lo trae una criatura enorme con alas de tormenta.","uses":[{"file":"data/maps.ts","line":292,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El jefe está ocupado. Volvé cuando seas un rival de verdad.","uses":[{"file":"data/maps.ts","line":330,"ctx":"Persona (aspecto grunt)","who":""}]},{"text":"En el fondo de la quebrada hay un arroyo.","uses":[{"file":"data/maps.ts","line":334,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Los cuervos de cabeza roja vuelan en círculos por arriba.","uses":[{"file":"data/maps.ts","line":334,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Treinta y Tres se llama así por los 33 Orientales.","uses":[{"file":"data/maps.ts","line":335,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Acá la historia está en cada rincón.","uses":[{"file":"data/maps.ts","line":335,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Un viento helado baja desde el cielo.","uses":[{"file":"data/maps.ts","line":338,"ctx":"Persona","who":""}]},{"text":"Rosario es un pueblo de paso, pero bien tranquilo.","uses":[{"file":"data/maps.ts","line":371,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Si te cansás, comprá mate en el almacén.","uses":[{"file":"data/maps.ts","line":371,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Acá se cría ganado de todos los tipos. Cada criatura tiene su lugar en el campo.","uses":[{"file":"data/maps.ts","line":372,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Un ombú solitario se alza en el campo. Su sombra parece moverse sin viento.","uses":[{"file":"data/maps.ts","line":375,"ctx":"Persona","who":""}]},{"text":"El viejo Observatorio del Cerro tiene la puerta clausurada con candados.","uses":[{"file":"data/maps.ts","line":400,"ctx":"Persona","who":""}]},{"text":"Un cartel dice: \"Cerrado por seguridad. Proyecto Pampero\".","uses":[{"file":"data/maps.ts","line":400,"ctx":"Persona","who":""}]},{"text":"Desde la cima del cerro se ve toda la costa.","uses":[{"file":"data/maps.ts","line":408,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El mar acá es más calmo que en Punta del Este.","uses":[{"file":"data/maps.ts","line":408,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Mi abuelo dice que en el mar de Piriápolis se ven toninas en verano.","uses":[{"file":"data/maps.ts","line":409,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"El faro de La Paloma guía a los barcos desde hace casi siglo y medio.","uses":[{"file":"data/maps.ts","line":444,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Más al este, en Cabo Polonio, no hay luz eléctrica.","uses":[{"file":"data/maps.ts","line":445,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Se vive con velas y con lo que da el mar.","uses":[{"file":"data/maps.ts","line":445,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"La puerta de la fábrica está sellada con candados. Hay mucha niebla en las sierras, y alguien adentro. Primero hay que despejar la niebla del este.","uses":[{"file":"data/maps.ts","line":475,"ctx":"Persona","who":""}]},{"text":"Un camino de ceniza baja hacia el oeste. El aire quema: todavía no estás listo para ese calor.","uses":[{"file":"data/maps.ts","line":477,"ctx":"Persona","who":""}]},{"text":"Minas es famosa por el agua de manantial y los cerros.","uses":[{"file":"data/maps.ts","line":482,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Dicen que en las noches de luna llena aparece un felino enorme en las sierras.","uses":[{"file":"data/maps.ts","line":482,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"En la vieja fábrica del este se mueve gente de gris, y de noche se oyen máquinas.","uses":[{"file":"data/maps.ts","line":483,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Un zarzal tapa la entrada. Con un machete se podría pasar.","uses":[{"file":"data/maps.ts","line":483,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Mi abuelo contaba que el yaguareté vivió por acá, antes de que se lo creyera extinto.","uses":[{"file":"data/maps.ts","line":484,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Entre los cerros, unos ojos dorados te observan. Una presencia enorme llena el aire.","uses":[{"file":"data/maps.ts","line":487,"ctx":"Persona","who":""}]},{"text":"Campeón. Volví a casa a entrenar.","uses":[{"file":"data/maps.ts","line":502,"ctx":"Persona (aspecto rival)","who":""}]},{"text":"La próxima vez en el Centenario te gano yo.","uses":[{"file":"data/maps.ts","line":502,"ctx":"Persona (aspecto rival)","who":""}]},{"text":"Soy ayudante del Maestro Tabárez.","uses":[{"file":"data/maps.ts","line":522,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"Estudiamos cómo las criaturas se adaptan al clima del Río de la Plata.","uses":[{"file":"data/maps.ts","line":522,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"El candombe nació en los barrios Sur y Palermo.","uses":[{"file":"data/maps.ts","line":529,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Cuando suenan los tambores, hasta las criaturas siguen el ritmo.","uses":[{"file":"data/maps.ts","line":529,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Existe un movimiento llamado Danza Candombe que sube Ataque y Velocidad.","uses":[{"file":"data/maps.ts","line":529,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Los Treinta y Tres Orientales cruzaron el río en 1825.","uses":[{"file":"data/maps.ts","line":535,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Coraje como ese se llama \"garra charrúa\".","uses":[{"file":"data/maps.ts","line":535,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Bienvenido al Palacio Salvo.","uses":[{"file":"data/maps.ts","line":549,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"Si tenés el Mapa de Uruguay, mirá cuántos lugares ya visitaste.","uses":[{"file":"data/maps.ts","line":549,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"En este palacio guardamos registros de todas las criaturas del país.","uses":[{"file":"data/maps.ts","line":550,"ctx":"Persona (aspecto prof)","who":""}]},{"text":"Algunas evolucionan al subir de nivel. Entrenalas con paciencia.","uses":[{"file":"data/maps.ts","line":550,"ctx":"Persona (aspecto prof)","who":""}]},{"text":"Dato útil: si una criatura está dormida o paralizada, es más fácil capturarla.","uses":[{"file":"data/maps.ts","line":551,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"El tipo Lucha es fuerte contra Normal, Roca y Siniestro.","uses":[{"file":"data/maps.ts","line":552,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Pero sufre contra Volador y Psíquico.","uses":[{"file":"data/maps.ts","line":552,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Siete años sin ganar un Siete. Hoy es mi día.","uses":[{"file":"data/maps.ts","line":634,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Bienvenido al Palacio de la Luz, sede de UTE.","uses":[{"file":"data/maps.ts","line":648,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"La presidenta Sofía usa criaturas de tipo Eléctrico.","uses":[{"file":"data/maps.ts","line":648,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Las de tipo Tierra no reciben daño eléctrico.","uses":[{"file":"data/maps.ts","line":648,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Planta de OSE de Punta del Este.","uses":[{"file":"data/maps.ts","line":658,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Lucía usa tipo Agua. Planta y Eléctrico tienen ventaja.","uses":[{"file":"data/maps.ts","line":658,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Gimnasio de Treinta y Tres.","uses":[{"file":"data/maps.ts","line":668,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El general Lavalleja usa tipo Roca y Tierra. Agua y Planta son tus mejores aliados.","uses":[{"file":"data/maps.ts","line":668,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Primero tenés que vencer a {rival}.","uses":[{"file":"data/maps.ts","line":692,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"El sol de la bandera aparece sobre la Torre de los Homenajes…","uses":[{"file":"data/maps.ts","line":696,"ctx":"Persona","who":""}]},{"text":"Calle Victoria: solo pasa quien venció a los tres veteranos del camino.","uses":[{"file":"data/maps.ts","line":972,"ctx":"Persona (Guardia de la Liga, aspecto cop)","who":"Guardia de la Liga"}]},{"text":"Es la regla de la Liga. Todavía te falta alguno.","uses":[{"file":"data/maps.ts","line":972,"ctx":"Persona (Guardia de la Liga, aspecto cop)","who":"Guardia de la Liga"}]},{"text":"El gimnasio del Correo está cerrado.","uses":[{"file":"data/maps.ts","line":1043,"ctx":"Persona","who":""}]},{"text":"Un cartel en la puerta dice: \"Volvemos pronto\".","uses":[{"file":"data/maps.ts","line":1043,"ctx":"Persona","who":""}]},{"text":"Soy cartero del Correo y hoy no tengo a quién entregarle nada: la presidenta no está.","uses":[{"file":"data/maps.ts","line":1048,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"Marta salió ayer a llevar un paquete por la cueva de Palmitas, al oeste, y no volvió.","uses":[{"file":"data/maps.ts","line":1048,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"Unos tipos de gris la seguían. Si vas para allá, andá con cuidado.","uses":[{"file":"data/maps.ts","line":1048,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"¡Marta volvió! Llegó con un paquete de planos y abrió el gimnasio.","uses":[{"file":"data/maps.ts","line":1049,"ctx":"Persona","who":""}]},{"text":"Gracias por ir a buscarla.","uses":[{"file":"data/maps.ts","line":1049,"ctx":"Persona","who":""}]},{"text":"Mi yegua lleva una semana acá y volvió más mansa que nunca.","uses":[{"file":"data/maps.ts","line":1072,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Se nota quién camina mucho: acá se les paga el tiempo en kilómetros.","uses":[{"file":"data/maps.ts","line":1072,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Dejé a mi bicho de compañero y ya cambió de forma. ¡Ni lo reconocí!","uses":[{"file":"data/maps.ts","line":1073,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Si dejás a uno que está por evolucionar, lo hace acá solo.","uses":[{"file":"data/maps.ts","line":1073,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Mi bici tiene dieciocho cambios. Con eso subo cualquier cuesta del norte.","uses":[{"file":"data/maps.ts","line":1094,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Dicen que la Ciclovía tiene tramos tan largos que ni se ve el final.","uses":[{"file":"data/maps.ts","line":1094,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Vine a arreglar una goma. Siempre se pincha en el peor momento.","uses":[{"file":"data/maps.ts","line":1095,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"A caballo no se pincha, pero tampoco se va al supermercado.","uses":[{"file":"data/maps.ts","line":1095,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"El Buquebus \"China Zorrilla\" zarpa pronto. Sin ticket no sube nadie.","uses":[{"file":"data/maps.ts","line":1425,"ctx":"Persona (Marinero del muelle, aspecto sailor)","who":"Marinero del muelle"}]},{"text":"Los pasajes los despachan en la empresa. Preguntá por el pueblo.","uses":[{"file":"data/maps.ts","line":1425,"ctx":"Persona (Marinero del muelle, aspecto sailor)","who":"Marinero del muelle"}]},{"text":"Todavía quedan entrenadores en el camino.","uses":[{"file":"data/route-stories.ts","line":169,"ctx":"addRouteStory","who":""}]},{"text":"El paso está cerrado. Un guardián pide una respuesta a quien quiera cruzar.","uses":[{"file":"data/route-stories.ts","line":188,"ctx":"Persona (Guardián del paso, evento route_riddle)","who":"Guardián del paso"}]},{"text":"La tranquera está trabada con tres cerrojos.","uses":[{"file":"data/route-stories.ts","line":294,"ctx":"Persona (Tranquera)","who":"Tranquera"}]},{"text":"Cada lado del camino tiene palancas que los mueven.","uses":[{"file":"data/route-stories.ts","line":294,"ctx":"Persona (Tranquera)","who":"Tranquera"}]},{"text":"Si te equivocás, los cerrojos vuelven a su lugar y se empieza de nuevo.","uses":[{"file":"data/route-stories.ts","line":298,"ctx":"Persona (Peón, aspecto gaucho)","who":"Peón"}]},{"text":"La máquina se apagó. Cuesta aceptarlo, pero no hay vuelta atrás.","uses":[{"file":"data/story.ts","line":288,"ctx":"fogChoice","who":""}]},{"text":"Con el tiempo nos vamos a acostumbrar. Gracias por frenarlos, {player}.","uses":[{"file":"data/story.ts","line":288,"ctx":"fogChoice","who":""}]},{"text":"{player}, por fin te levantaste.","uses":[{"file":"data/story.ts","line":294,"ctx":"mom","who":"Madre"}]},{"text":"El Maestro Tabárez te espera en su laboratorio.","uses":[{"file":"data/story.ts","line":294,"ctx":"mom","who":"Madre"}]},{"text":"Es el edificio de techo violeta. Hoy empieza tu viaje.","uses":[{"file":"data/story.ts","line":294,"ctx":"mom","who":"Madre"}]},{"text":"Sentate y descansá un rato.","uses":[{"file":"data/story.ts","line":297,"ctx":"mom","who":"Madre"}]},{"text":"Te cebo unos mates.","uses":[{"file":"data/story.ts","line":297,"ctx":"mom","who":"Madre"}]},{"text":"Listo. Tus criaturas están recuperadas. Cuidate.","uses":[{"file":"data/story.ts","line":299,"ctx":"mom","who":"Madre"}]},{"text":"Hola, {player}. {rival} ya salió para el laboratorio.","uses":[{"file":"data/story.ts","line":304,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Siempre quiere ser el primero en todo.","uses":[{"file":"data/story.ts","line":304,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Tomá, llevate esto para el viaje.","uses":[{"file":"data/story.ts","line":304,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Mucha suerte en el viaje. Si ves a {rival}, decile que llame a casa.","uses":[{"file":"data/story.ts","line":308,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Llegaste, {player}.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"},{"file":"data/story.ts","line":1090,"ctx":"rival_final","who":"{rival}"}]},{"text":"Soy el Maestro Tabárez. Durante años dirigí a la selección; hoy estudio a las criaturas del Uruguay.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Viven en los montes, las playas, las sierras y hasta en la Rambla.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Hoy vas a elegir a tu primer compañero.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"En la mesa hay tres Pokeballs. Elegí con calma: esa criatura te va a acompañar mucho tiempo.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"{rival} es mi sobrino. Creció entre apuntes y Pokeballs, así que no te la va a hacer fácil.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Hace años estudié el clima del Río de la Plata junto a un colega, Dr. Díaz. Hoy no sé dónde anda, pero el Cardenal Azul sigue siendo un misterio.","uses":[{"file":"data/story.ts","line":316,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"¿Y yo? Llegué primero.","uses":[{"file":"data/story.ts","line":325,"ctx":"prof","who":"{rival}"}]},{"text":"Paciencia, {rival}. Vos elegís después.","uses":[{"file":"data/story.ts","line":326,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Elegí una de las Pokeballs de la mesa.","uses":[{"file":"data/story.ts","line":328,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"¡La carta! Gracias, {player}.","uses":[{"file":"data/story.ts","line":335,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Es de un viejo colega. Dice que el Cardenal Azul se vio por el litoral.","uses":[{"file":"data/story.ts","line":335,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Como prometí: la PokeDex. Registra cada criatura que veas o captures.","uses":[{"file":"data/story.ts","line":336,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Y unas Pokeballs para capturar criaturas salvajes.","uses":[{"file":"data/story.ts","line":336,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Te pedí una carta del almacén de Colonia del Sacramento, siguiendo la Ruta 21.","uses":[{"file":"data/story.ts","line":342,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Cuando la tengas, traémela y te doy la PokeDex.","uses":[{"file":"data/story.ts","line":342,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Antes de elegir, tenés que hablar con el Maestro Tabárez.","uses":[{"file":"data/story.ts","line":354,"ctx":"starter","who":""}]},{"text":"Tiene desventaja contra el tuyo, pero no pienso ponértelo fácil.","uses":[{"file":"data/story.ts","line":370,"ctx":"starter","who":"{rival}"}]},{"text":"{player}, probemos a nuestras criaturas.","uses":[{"file":"data/story.ts","line":371,"ctx":"starter","who":"{rival}"}]},{"text":"Combatamos.","uses":[{"file":"data/story.ts","line":371,"ctx":"starter","who":"{rival}"}]},{"text":"Gané. Sigo siendo mejor.","uses":[{"file":"data/story.ts","line":374,"ctx":"starter","who":"{rival}"}]},{"text":"Igual, tu criatura tiene potencial.","uses":[{"file":"data/story.ts","line":374,"ctx":"starter","who":"{rival}"}]},{"text":"Fue suerte.","uses":[{"file":"data/story.ts","line":375,"ctx":"starter","who":"{rival}"}]},{"text":"Voy a entrenar hasta superarte.","uses":[{"file":"data/story.ts","line":375,"ctx":"starter","who":"{rival}"}]},{"text":"Buen combate. Ya atendí a sus criaturas.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Ahora, {player}: el país es grande. Hay doce Gimnasios, y el camino empieza acá, en Carmelo, y termina en Montevideo.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Si conseguís las doce medallas, podés desafiar a la Liga en el Estadio Centenario.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Y tené cuidado con el Equipo PP. Últimamente aparece una niebla extraña en el litoral.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Tu madre puede curar a tus criaturas en casa.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Antes de irte, {player}, te pido un favor. En el almacén de Colonia del Sacramento me guardan una carta.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Seguí por la Ruta 21, entrenando en los pastizales y contra quien te desafíe. No vuelvas hasta tenerla.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Traémela y te entrego la PokeDex y unas Pokeballs. Buen viaje.","uses":[{"file":"data/story.ts","line":377,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Que tengas buen viaje. Y tomá mate, que ayuda.","uses":[{"file":"data/story.ts","line":389,"ctx":"gift_te_marcela","who":"Abuelo"}]},{"text":"Un entrenador joven. Tomá, para el camino.","uses":[{"file":"data/story.ts","line":390,"ctx":"gift_te_marcela","who":"Abuelo"}]},{"text":"El Mapa de Uruguay te muestra dónde estás y qué lugares ya visitaste.","uses":[{"file":"data/story.ts","line":396,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Abrilo desde el menú o con la tecla T.","uses":[{"file":"data/story.ts","line":396,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Bienvenido a Colonia del Sacramento. Trabajo en la oficina de turismo del puerto.","uses":[{"file":"data/story.ts","line":397,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Tomá, un mapa del país. Te marca las ciudades y las localidades.","uses":[{"file":"data/story.ts","line":397,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Entre ciudad y ciudad hay localidades sin gimnasio, pero con almacenes y gente con cosas útiles.","uses":[{"file":"data/story.ts","line":400,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Pesqué en estos arroyos toda la vida.","uses":[{"file":"data/story.ts","line":404,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Somos tres hermanos pescadores: uno pesca en el muelle de Paysandú, otro vive en Minas y el menor tiene casa en Paysandú.","uses":[{"file":"data/story.ts","line":404,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Cada uno te da una caña mejor, pero hay que ganársela con medallas.","uses":[{"file":"data/story.ts","line":404,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Parate frente al agua y apretá A. Con esta caña solo pican las criaturas más comunes. Mi hermano en Minas tiene una mejor.","uses":[{"file":"data/story.ts","line":409,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"¿Qué hacés, guri, todo tranquilo? ¿Te gusta la pesca?","uses":[{"file":"data/story.ts","line":410,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"¿Por qué no te agarrás una de esas cañas viejas que tengo ahí de sobra?","uses":[{"file":"data/story.ts","line":410,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"Parate frente al agua y apretá el botón A. Con esta caña solo pican las criaturas más comunes. Más adelante, mi hermano de Minas te dará una mejor.","uses":[{"file":"data/story.ts","line":413,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"Con la Caña Buena pican criaturas más grandes. La Súper Caña la tiene mi hermano menor, en Paysandú.","uses":[{"file":"data/story.ts","line":417,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"En el muelle de Paysandú hay un pescador que regala una caña para empezar. Pasá primero por ahí.","uses":[{"file":"data/story.ts","line":418,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Veo que ya sabés pescar.","uses":[{"file":"data/story.ts","line":419,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Todavía te falta camino: volvé con tres medallas y te doy una caña buena.","uses":[{"file":"data/story.ts","line":419,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Venís con tres medallas, y eso se nota en el trato con las criaturas.","uses":[{"file":"data/story.ts","line":420,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Tomá: una caña buena, con mejor carnada.","uses":[{"file":"data/story.ts","line":420,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Con ella pican criaturas de más nivel. Mi hermano menor, en Paysandú, guarda la mejor.","uses":[{"file":"data/story.ts","line":423,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Con la Súper Caña puede picar cualquier cosa. Tené cuidado con lo que sacás.","uses":[{"file":"data/story.ts","line":427,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Mi hermano de Minas tiene la caña buena. Pasá primero por ahí.","uses":[{"file":"data/story.ts","line":428,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"La Súper Caña no es para cualquiera.","uses":[{"file":"data/story.ts","line":429,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Volvé con siete medallas y es tuya.","uses":[{"file":"data/story.ts","line":429,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Siete medallas. Mis hermanos no se equivocaron con vos.","uses":[{"file":"data/story.ts","line":430,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Esta es la mejor caña que armé en mi vida.","uses":[{"file":"data/story.ts","line":430,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Con ella pican todas las criaturas de la zona, incluso las más raras y fuertes.","uses":[{"file":"data/story.ts","line":433,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"El Cuareim es manso, pero hay que respetarlo. La Canoa solo resiste con la Medalla Rivera.","uses":[{"file":"data/story.ts","line":437,"ctx":"gift_surf","who":"Pescador"}]},{"text":"Vivo a orillas del río desde que nací.","uses":[{"file":"data/story.ts","line":438,"ctx":"gift_surf","who":"Pescador"}]},{"text":"Te regalo esta canoa. Caminá hacia el agua y subís sola.","uses":[{"file":"data/story.ts","line":438,"ctx":"gift_surf","who":"Pescador"}]},{"text":"Ojo: las corrientes de más al este son fuertes. Hace falta la Medalla Rivera para animarse.","uses":[{"file":"data/story.ts","line":438,"ctx":"gift_surf","who":"Pescador"}]},{"text":"En las cuevas, las cascadas esconden cornisas. Subí con la soga y fijate qué guardan.","uses":[{"file":"data/story.ts","line":444,"ctx":"gift_soga","who":"Escalador"}]},{"text":"Trepé cuanta pared hay entre Fray Bentos y Rivera, y ya no me quedan fuerzas para más.","uses":[{"file":"data/story.ts","line":445,"ctx":"gift_soga","who":"Escalador"}]},{"text":"Llevate mi soga. En las cuevas hay cascadas que caen sobre cornisas escondidas.","uses":[{"file":"data/story.ts","line":445,"ctx":"gift_soga","who":"Escalador"}]},{"text":"Caminá contra la cascada y subís; para bajar, caminá hacia abajo desde la cornisa.","uses":[{"file":"data/story.ts","line":445,"ctx":"gift_soga","who":"Escalador"}]},{"text":"Con esos guantes movés lo que quieras. Pero la Medalla Tacuarembó es la que te da el derecho.","uses":[{"file":"data/story.ts","line":451,"ctx":"gift_fuerza","who":"Domador"}]},{"text":"Domo potros hace años y no hay animal que me gane de fuerza.","uses":[{"file":"data/story.ts","line":452,"ctx":"gift_fuerza","who":"Domador"}]},{"text":"Llevate estos guantes. Con ellos podés empujar rocas pesadas, caminando contra ellas.","uses":[{"file":"data/story.ts","line":452,"ctx":"gift_fuerza","who":"Domador"}]},{"text":"Solo te van a servir si ganás la Medalla Tacuarembó.","uses":[{"file":"data/story.ts","line":452,"ctx":"gift_fuerza","who":"Domador"}]},{"text":"Alquilo esta casa todos los veranos. Llevate unos alfajores, que me sobraron.","uses":[{"file":"data/story.ts","line":459,"ctx":"gift_pir","who":"Veraneante"}]},{"text":"Cada verano vienen turistas de todo el continente.","uses":[{"file":"data/story.ts","line":463,"ctx":"gift_pir","who":"Veraneante"}]},{"text":"Me mudé acá por las olas. Tomá, unas Superballs que ya no uso.","uses":[{"file":"data/story.ts","line":468,"ctx":"gift_pal","who":"Surfista"}]},{"text":"Si te gusta el mar, no dejes de probar la pesca en La Paloma.","uses":[{"file":"data/story.ts","line":472,"ctx":"gift_pal","who":"Surfista"}]},{"text":"El viento de Florida no para nunca. Con el hornero ya podés cruzar el país en un rato.","uses":[{"file":"data/story.ts","line":476,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Acá el viento llega de todos lados, y mis horneros aprendieron a usarlo.","uses":[{"file":"data/story.ts","line":477,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Llevate este silbato. Si silbás, un hornero te lleva volando a cualquier ciudad que ya conozcas.","uses":[{"file":"data/story.ts","line":477,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Se usa desde el menú, en la opción Vuelo. Eso sí: el hornero solo te obedece si ganaste la Medalla Florida.","uses":[{"file":"data/story.ts","line":477,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Mi plan fracasó. Esta vez de verdad.","uses":[{"file":"data/story.ts","line":483,"ctx":"garua","who":"Garúa"}]},{"text":"Así que lograste llegar hasta acá. Otra vez.","uses":[{"file":"data/story.ts","line":484,"ctx":"garua","who":"Garúa"}]},{"text":"Te dije que el plan de la Represa era un ensayo.","uses":[{"file":"data/story.ts","line":484,"ctx":"garua","who":"Garúa"}]},{"text":"Brumario cayó y Bruma también, pero las máquinas siguen en pie. Con ellas, la niebla vuelve en cuestión de semanas.","uses":[{"file":"data/story.ts","line":484,"ctx":"garua","who":"Garúa"}]},{"text":"Desde esta fábrica se va a gobernar el clima del país.","uses":[{"file":"data/story.ts","line":484,"ctx":"garua","who":"Garúa"}]},{"text":"Está bien. Me rindo. Por ahora.","uses":[{"file":"data/story.ts","line":489,"ctx":"garua","who":"Garúa"}]},{"text":"Pero no soy quien manda. PP quiere decir Proyecto Pampero, y el proyecto es del Dr. Díaz.","uses":[{"file":"data/story.ts","line":489,"ctx":"garua","who":"Garúa"}]},{"text":"Dr. Díaz dejó el Anglo hace tiempo. Hoy espera en Montevideo, en el puerto, a quien llegue con las doce medallas.","uses":[{"file":"data/story.ts","line":489,"ctx":"garua","who":"Garúa"}]},{"text":"Llevate esto.","uses":[{"file":"data/story.ts","line":489,"ctx":"garua","who":"Garúa"}]},{"text":"En la oficina de Garúa encontrás una vianda con Restos de Asado, guardada para la guardia nocturna.","uses":[{"file":"data/story.ts","line":491,"ctx":"garua","who":""}]},{"text":"Las máquinas de la fábrica se apagaron. Solo falta Dr. Díaz, en Montevideo.","uses":[{"file":"data/story.ts","line":494,"ctx":"garua","who":""}]},{"text":"El calor se aguanta mejor con un buen mate.","uses":[{"file":"data/story.ts","line":499,"ctx":"gift_dur","who":"Vecino"}]},{"text":"No es fácil vivir con este calor.","uses":[{"file":"data/story.ts","line":500,"ctx":"gift_dur","who":"Vecino"}]},{"text":"Pero la gente de acá se las arregla. Llevate esto, que no lo uso.","uses":[{"file":"data/story.ts","line":500,"ctx":"gift_dur","who":"Vecino"}]},{"text":"Un buen mate se toma despacio y con buena compañía.","uses":[{"file":"data/story.ts","line":507,"ctx":"gift_min","who":"Paisano"}]},{"text":"Los de acá tomamos mate con el agua de las sierras. Probalo, que es de lo mejor.","uses":[{"file":"data/story.ts","line":508,"ctx":"gift_min","who":"Paisano"}]},{"text":"Los carritos de garrapiñada de la Rambla son un clásico.","uses":[{"file":"data/story.ts","line":514,"ctx":"gift_garrapinada","who":"Vecina"}]},{"text":"Compré garrapiñada en la Rambla. Tomá una: hace que tu criatura suba de nivel.","uses":[{"file":"data/story.ts","line":515,"ctx":"gift_garrapinada","who":"Vecina"}]},{"text":"¡{player}! Sabía que ibas a pasar por acá.","uses":[{"file":"data/story.ts","line":523,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Ya tengo la PokeDex llena de apuntes. Vos recién arrancás.","uses":[{"file":"data/story.ts","line":523,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Mi tío dice que en el litoral hay niebla rara. Yo voy a Trinidad por la medalla. Pero antes, una revancha.","uses":[{"file":"data/story.ts","line":523,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Te gané. Así es como se entrena.","uses":[{"file":"data/story.ts","line":529,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Ya curé a tus criaturas: no quiero ganarte con ventaja.","uses":[{"file":"data/story.ts","line":529,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Nos vemos en Trinidad. Si llegás primero, no le ganes a Elena antes que yo.","uses":[{"file":"data/story.ts","line":530,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"{player}, te estaba esperando.","uses":[{"file":"data/story.ts","line":536,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Me enteré de que le ganaste a Zoraida, en el Anglo.","uses":[{"file":"data/story.ts","line":536,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Yo también estuve entrenando. Veamos quién está más fuerte.","uses":[{"file":"data/story.ts","line":536,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Yo sigo hacia Salto. Nos vemos allá.","uses":[{"file":"data/story.ts","line":539,"ctx":"rival_mvd","who":"{rival}"},{"file":"data/story.ts","line":542,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Esta vez gané yo. Entrená un poco más y volvé a intentarlo cuando quieras.","uses":[{"file":"data/story.ts","line":542,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Tus criaturas quedaron recuperadas.","uses":[{"file":"data/story.ts","line":543,"ctx":"rival_mvd","who":""},{"file":"data/story.ts","line":710,"ctx":"leader","who":""},{"file":"data/story.ts","line":721,"ctx":"leader","who":""},{"file":"data/story.ts","line":773,"ctx":"rival_ferry","who":""},{"file":"data/story.ts","line":915,"ctx":"rival_r5","who":""},{"file":"data/story.ts","line":929,"ctx":"rival_r24","who":""},{"file":"data/story.ts","line":1097,"ctx":"rival_final","who":""}]},{"text":"Bienvenido a la Policlínica.","uses":[{"file":"data/story.ts","line":549,"ctx":"nurse","who":"Enfermera"}]},{"text":"Vamos a atender a tus criaturas.","uses":[{"file":"data/story.ts","line":549,"ctx":"nurse","who":"Enfermera"}]},{"text":"Listo, están recuperadas. Volvé cuando lo necesites.","uses":[{"file":"data/story.ts","line":552,"ctx":"nurse","who":"Enfermera"}]},{"text":"Armé este puesto para los que van a la Liga. Todos llegan con las criaturas cansadas.","uses":[{"file":"data/story.ts","line":556,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"Dejame que las atienda.","uses":[{"file":"data/story.ts","line":556,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"Listo. Que la Calle Victoria te sea corta.","uses":[{"file":"data/story.ts","line":558,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"¿Venís de parte del Maestro Tabárez? Te estaba esperando.","uses":[{"file":"data/story.ts","line":569,"ctx":"shop_carta","who":"Almacenero"}]},{"text":"Tengo esta carta para él. Llevásela con cuidado.","uses":[{"file":"data/story.ts","line":569,"ctx":"shop_carta","who":"Almacenero"}]},{"text":"Si te animás a buscarla, empezá por la cueva de Palmitas: ahí la vieron por última vez.","uses":[{"file":"data/story.ts","line":586,"ctx":"cartero_marta","who":"Cartero"}]},{"text":"Soy Marta, del Correo. Me siguieron hasta acá para quitarme un paquete con planos.","uses":[{"file":"data/story.ts","line":593,"ctx":"marta_cave","who":"Marta"}]},{"text":"Los reclutas del PP me cierran el paso. Si los vencés, te lo agradezco.","uses":[{"file":"data/story.ts","line":593,"ctx":"marta_cave","who":"Marta"}]},{"text":"Gracias, {player}. Sin vos seguiría encerrada entre esas rocas.","uses":[{"file":"data/story.ts","line":594,"ctx":"marta_cave","who":"Marta"}]},{"text":"Llevaban los planos de unas máquinas de niebla. Esto lo tiene que ver todo el país.","uses":[{"file":"data/story.ts","line":594,"ctx":"marta_cave","who":"Marta"}]},{"text":"Ya no hace falta que me trates de usted. Después de esto, somos amigos.","uses":[{"file":"data/story.ts","line":594,"ctx":"marta_cave","who":"Marta"}]},{"text":"Voy ahora mismo para el gimnasio. Cuando llegues, me va a gustar medir tu equipo.","uses":[{"file":"data/story.ts","line":594,"ctx":"marta_cave","who":"Marta"}]},{"text":"Gracias de nuevo. Ojalá todos fueran como vos.","uses":[{"file":"data/story.ts","line":600,"ctx":"route_quest","who":""}]},{"text":"Apagaste la máquina. La niebla de la zona empieza a levantarse. Dentro hay una bolsa con provisiones.","uses":[{"file":"data/story.ts","line":614,"ctx":"route_fog","who":"Máquina de niebla"}]},{"text":"Bienvenido al Casino Peninsula. Las fichas no se cambian por dinero, solo por premios.","uses":[{"file":"data/story.ts","line":620,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Diez fichas salen $500.","uses":[{"file":"data/story.ts","line":620,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Suerte en las máquinas.","uses":[{"file":"data/story.ts","line":622,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Ya llevás demasiadas fichas. Jugá algunas antes.","uses":[{"file":"data/story.ts","line":624,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"No te alcanza el dinero.","uses":[{"file":"data/story.ts","line":625,"ctx":"casino_cashier","who":"Cajero"},{"file":"game/world.ts","line":1019,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1075,"ctx":"criadero","who":""}]},{"text":"Tragamonedas. Tres iguales pagan; Siete Siete Siete es el premio mayor.","uses":[{"file":"data/story.ts","line":633,"ctx":"casino_slots","who":"Máquina"}]},{"text":"No tenés fichas suficientes.","uses":[{"file":"data/story.ts","line":639,"ctx":"casino_slots","who":"Máquina"}]},{"text":"Mostrador de premios. Se paga solo con fichas.","uses":[{"file":"data/story.ts","line":653,"ctx":"casino_prizes","who":"Premios"}]},{"text":"Volvé cuando tengas más fichas.","uses":[{"file":"data/story.ts","line":656,"ctx":"casino_prizes","who":"Premios"}]},{"text":"No te alcanzan las fichas.","uses":[{"file":"data/story.ts","line":658,"ctx":"casino_prizes","who":"Premios"}]},{"text":"Volvé cuando tus criaturas estén listas. No los dejes salirse con la suya.","uses":[{"file":"data/story.ts","line":682,"ctx":"town_gate","who":""}]},{"text":"Antes de dejar pasar a alguien, quiero ver cómo trata a sus criaturas.","uses":[{"file":"data/story.ts","line":687,"ctx":"town_gate","who":""}]},{"text":"Entrená un poco y volvé. No hay apuro.","uses":[{"file":"data/story.ts","line":690,"ctx":"town_gate","who":""}]},{"text":"Volviste. Estuve entrenando desde la última vez.","uses":[{"file":"data/story.ts","line":704,"ctx":"leader","who":""}]},{"text":"Esta vez no me contengo.","uses":[{"file":"data/story.ts","line":704,"ctx":"leader","who":""}]},{"text":"Buen combate. Volvé cuando hayas recorrido más camino.","uses":[{"file":"data/story.ts","line":711,"ctx":"leader","who":""}]},{"text":"Tomá también esta MT. Enseña un movimiento nuevo a una criatura compatible.","uses":[{"file":"data/story.ts","line":727,"ctx":"leader","who":""}]},{"text":"Otra vez vos.","uses":[{"file":"data/story.ts","line":732,"ctx":"bruma","who":"Bruma"}]},{"text":"Sin la lámpara del faro, la niebla cubre la costa y nadie ve lo que hacemos.","uses":[{"file":"data/story.ts","line":732,"ctx":"bruma","who":"Bruma"}]},{"text":"Esta vez no hay torre que te frene. Vas a tener que pasar por mí.","uses":[{"file":"data/story.ts","line":732,"ctx":"bruma","who":"Bruma"}]},{"text":"Llevate tu lámpara.","uses":[{"file":"data/story.ts","line":735,"ctx":"bruma","who":"Bruma"}]},{"text":"Igual es tarde: Garúa ya puso a funcionar la fábrica de Minas.","uses":[{"file":"data/story.ts","line":735,"ctx":"bruma","who":"Bruma"}]},{"text":"Y Dr. Díaz nos espera en Montevideo.","uses":[{"file":"data/story.ts","line":735,"ctx":"bruma","who":"Bruma"}]},{"text":"Deberías devolverle la lámpara al farero. Está dentro del faro.","uses":[{"file":"data/story.ts","line":739,"ctx":"bruma","who":""}]},{"text":"La lámpara. La recuperaste.","uses":[{"file":"data/story.ts","line":744,"ctx":"keeper","who":"Farero"}]},{"text":"Esta noche el faro de Cabo Polonio vuelve a funcionar.","uses":[{"file":"data/story.ts","line":744,"ctx":"keeper","who":"Farero"}]},{"text":"Aceptá esto, es lo menos que puedo hacer.","uses":[{"file":"data/story.ts","line":744,"ctx":"keeper","who":"Farero"}]},{"text":"Y llevate también este farol de gaucho. Alumbra hasta el túnel más oscuro.","uses":[{"file":"data/story.ts","line":747,"ctx":"keeper","who":"Farero"}]},{"text":"Las sierras entre Piriápolis y Minas son pura oscuridad: lo vas a necesitar.","uses":[{"file":"data/story.ts","line":747,"ctx":"keeper","who":"Farero"}]},{"text":"Se usa desde el menú, en Destello. Eso sí: solo te va a obedecer si ganaste la Medalla Maldonado.","uses":[{"file":"data/story.ts","line":747,"ctx":"keeper","who":"Farero"}]},{"text":"Gracias a vos, los barcos navegan seguros.","uses":[{"file":"data/story.ts","line":752,"ctx":"keeper","who":"Farero"}]},{"text":"Se llevaron la lámpara. Fue una mujer vestida de gris, con capa.","uses":[{"file":"data/story.ts","line":753,"ctx":"keeper","who":"Farero"}]},{"text":"Sigue afuera, del lado de las rocas.","uses":[{"file":"data/story.ts","line":753,"ctx":"keeper","who":"Farero"}]},{"text":"Las máquinas que había en las cámaras de frío no eran de la fábrica. Las trajo alguien de afuera.","uses":[{"file":"data/story.ts","line":759,"ctx":"frb_historia","who":""}]},{"text":"Y esa niebla artificial que se vende por el litoral, creo que no es una casualidad.","uses":[{"file":"data/story.ts","line":759,"ctx":"frb_historia","who":""}]},{"text":"Esta ciudad fue la cocina del mundo. Que no sea ahora un depósito de máquinas ajenas.","uses":[{"file":"data/story.ts","line":759,"ctx":"frb_historia","who":""}]},{"text":"Veo que pasaste por el museo. Zoraida cuida ese lugar como a un tesoro.","uses":[{"file":"data/story.ts","line":760,"ctx":"frb_historia","who":""}]},{"text":"Las cajas del museo se usaban para despachar mercadería entre depósitos. Ahora las usa ella para recibir a los visitantes.","uses":[{"file":"data/story.ts","line":760,"ctx":"frb_historia","who":""}]},{"text":"Si te interesa la historia del Anglo, andá a ver el frigorífico viejo. Pero con cuidado: se movió gente rara por ahí.","uses":[{"file":"data/story.ts","line":760,"ctx":"frb_historia","who":""}]},{"text":"Soy docente de historia. Fray Bentos nació alrededor de una fábrica de extracto de carne, hace más de un siglo y medio.","uses":[{"file":"data/story.ts","line":761,"ctx":"frb_historia","who":""}]},{"text":"El Anglo faenaba miles de reses por día y mandaba conservas a medio mundo. Por eso le decían \"la cocina del mundo\".","uses":[{"file":"data/story.ts","line":761,"ctx":"frb_historia","who":""}]},{"text":"Hoy el museo guarda esa historia. Preguntá por Zoraida, la directora.","uses":[{"file":"data/story.ts","line":761,"ctx":"frb_historia","who":""}]},{"text":"{player}. Sabía que ibas a subir a este barco.","uses":[{"file":"data/story.ts","line":766,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Alguien me escribió diciendo que trabaja con mi tío en un estudio del clima. Me pidió ayuda y le pasé un par de datos del laboratorio.","uses":[{"file":"data/story.ts","line":766,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Si es ciencia, quiero ser parte. Pero antes de que entres al camarote del capitán, veamos quién es más fuerte.","uses":[{"file":"data/story.ts","line":766,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Bien. Pasá vos primero, el capitán te espera.","uses":[{"file":"data/story.ts","line":769,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Pero en el Centenario te gano.","uses":[{"file":"data/story.ts","line":769,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Todavía te falta. No pasa nada: entrená y volvé a medirte conmigo en el Centenario.","uses":[{"file":"data/story.ts","line":772,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Dejo el paso libre al camarote del capitán.","uses":[{"file":"data/story.ts","line":772,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Cuando la ballena canta, hasta el motor del barco parece callarse.","uses":[{"file":"data/story.ts","line":779,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"Soy biólogo marino. Viajo para estudiar a la criatura que canta frente a Punta del Este.","uses":[{"file":"data/story.ts","line":780,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"Mirá estas fotos: una ballena enorme, de color plata, que solo aparece en invierno.","uses":[{"file":"data/story.ts","line":780,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"¡Los datos de Ballenaplata se agregaron a la PokeDex!","uses":[{"file":"data/story.ts","line":784,"ctx":"ferry_bio","who":""}]},{"text":"Además, entre las cosas del capataz había un objeto que sirve para equipar a una criatura.","uses":[{"file":"data/story.ts","line":801,"ctx":"event_boss","who":""}]},{"text":"PEAJE","uses":[{"file":"data/story.ts","line":809,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Gracias. Buen viaje y cuidado con las criaturas en la ruta.","uses":[{"file":"data/story.ts","line":812,"ctx":"toll_booth","who":"Peaje"}]},{"text":"¿Otra vez sin plata? Bueno, ya van varias veces.","uses":[{"file":"data/story.ts","line":817,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Está bien, por esta vez pasás. Pero lo vas a pagar con la patente, como todo en este país.","uses":[{"file":"data/story.ts","line":817,"ctx":"toll_booth","who":"Peaje"}]},{"text":"No te alcanza para el peaje. Volvé cuando tengas $115.","uses":[{"file":"data/story.ts","line":821,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Gracias otra vez, {player}. Sin vos esto seguiría tomado.","uses":[{"file":"data/story.ts","line":827,"ctx":"event_owner","who":"Dueño"}]},{"text":"Pasá cuando quieras.","uses":[{"file":"data/story.ts","line":827,"ctx":"event_owner","who":"Dueño"}]},{"text":"Mi hermano ya no está mareado. Gracias por el favor.","uses":[{"file":"data/story.ts","line":832,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"El Buquebus \"China Zorrilla\" está en la terminal, al lado del muelle.","uses":[{"file":"data/story.ts","line":833,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Mi hermano, el capitán, está en su camarote. Llevale un Mate: en el almacén venden.","uses":[{"file":"data/story.ts","line":833,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Soy el farero de Fray Bentos. Hace cuarenta años que miro el río desde acá arriba.","uses":[{"file":"data/story.ts","line":834,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Mi hermano es el capitán del Buquebus \"China Zorrilla\", el ferry nuevo que lleva el nombre de la actriz. Está atracado en la terminal.","uses":[{"file":"data/story.ts","line":834,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Desde la prueba de mar anda mareado, y no hay nada que lo calme como un Mate bien cebado.","uses":[{"file":"data/story.ts","line":834,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Para subir hace falta un ticket, y los reparte alguien de la empresa. Yo solo sé que hay gente de la planta que trabaja en el frigorífico a la fuerza.","uses":[{"file":"data/story.ts","line":834,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Gracias por la credencial. Cuando salgas de este laberinto, subí al barco con el ticket.","uses":[{"file":"data/story.ts","line":839,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"¡Esa es mi credencial! Pero con la jefa de la banda acá adentro no puedo despachar ningún pasaje.","uses":[{"file":"data/story.ts","line":841,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si ella se va, el ticket es tuyo. Quedate con la credencial hasta entonces.","uses":[{"file":"data/story.ts","line":841,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"¡Esa es mi credencial! Estaba perdida en alguna de las cintas.","uses":[{"file":"data/story.ts","line":844,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"No soy del PP. Me tienen acá adentro manejando las cintas porque soy el único que las conoce.","uses":[{"file":"data/story.ts","line":846,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Soy de los que despachan los pasajes del Buquebus. Tomá uno, es lo mínimo.","uses":[{"file":"data/story.ts","line":846,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si el capitán anda mareado, llevale un Mate. Dicen que es lo único que lo calma.","uses":[{"file":"data/story.ts","line":849,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Yo trabajo en el Anglo desde antes de que llegaran estos del PP. Me tienen encerrado en esta oficina, a la vista de la jefa.","uses":[{"file":"data/story.ts","line":851,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Perdí mi credencial de operario en algún rincón de las cintas y sin ella no puedo ni salir a cobrar.","uses":[{"file":"data/story.ts","line":851,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si la encontrás, hablamos. Yo despacho los pasajes del Buquebus.","uses":[{"file":"data/story.ts","line":851,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Uf… perdón. Soy el capitán de este barco, y estoy mareado desde que zarpamos de prueba.","uses":[{"file":"data/story.ts","line":856,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Lo único que me calma es un Mate, de esos bien cebados. Pero acá a bordo se acabó la yerba.","uses":[{"file":"data/story.ts","line":856,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Si me traés un Mate, te lo voy a agradecer toda la vida.","uses":[{"file":"data/story.ts","line":857,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"En el almacén de Fray Bentos venden.","uses":[{"file":"data/story.ts","line":857,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"El capitán suspira. Cuando quieras, acá estoy.","uses":[{"file":"data/story.ts","line":858,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"{player} le dio el Mate al capitán. Poco a poco recupera el color.","uses":[{"file":"data/story.ts","line":861,"ctx":"ferry_captain","who":""}]},{"text":"Mucho mejor. Me salvaste, {player}.","uses":[{"file":"data/story.ts","line":862,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"En agradecimiento, tomá este machete: lo uso para abrir paso entre los zarzales del muelle viejo.","uses":[{"file":"data/story.ts","line":862,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Se usa parándote frente al zarzal y apretando A. En Fray Bentos la guardia solo deja cortar a quien ganó la Medalla de este pueblo; en los caminos más al norte, a quien ganó la Medalla Salto.","uses":[{"file":"data/story.ts","line":862,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"También te dejo unas Pokeballs y unos panes que el barco no va a usar.","uses":[{"file":"data/story.ts","line":865,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Ahora, a trabajar: el barco zarpa en minutos rumbo a Buenos Aires.","uses":[{"file":"data/story.ts","line":871,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Todos los pasajeros tienen que bajar. ¡Gracias por todo!","uses":[{"file":"data/story.ts","line":871,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"El Buquebus \"China Zorrilla\" ya no se ve en el río. No va a volver a este puerto.","uses":[{"file":"data/story.ts","line":874,"ctx":"ferry_captain","who":""}]},{"text":"Con el Machete vas a poder abrir los zarzales de la salida norte de Fray Bentos cuando ganes la Medalla del gimnasio del pueblo.","uses":[{"file":"data/story.ts","line":875,"ctx":"ferry_captain","who":""}]},{"text":"Una figura pálida sostiene un farol apagado.","uses":[{"file":"data/story.ts","line":880,"ctx":"anima","who":"Ánima"}]},{"text":"Soy el Sereno de la torre. Alguien me sacó el farol y escondió acá una pieza que apaga todo.","uses":[{"file":"data/story.ts","line":880,"ctx":"anima","who":"Ánima"}]},{"text":"No me dejan descansar. Si querés llevarte la pieza, antes tenés que vencerme.","uses":[{"file":"data/story.ts","line":880,"ctx":"anima","who":"Ánima"}]},{"text":"El farol se prende solo. La pieza de la máquina queda en el suelo, apagada.","uses":[{"file":"data/story.ts","line":885,"ctx":"anima","who":"Ánima"}]},{"text":"Gracias. Ahora puedo descansar.","uses":[{"file":"data/story.ts","line":885,"ctx":"anima","who":"Ánima"}]},{"text":"Llevate esto: lo usaban los serenos para ver en la oscuridad.","uses":[{"file":"data/story.ts","line":885,"ctx":"anima","who":"Ánima"}]},{"text":"Desde la ventana de la torre, las Luces Malas de Cerro Largo se apagan una por una.","uses":[{"file":"data/story.ts","line":889,"ctx":"anima","who":""}]},{"text":"Así que vos sos el entrenador que molesta a mis reclutas.","uses":[{"file":"data/story.ts","line":893,"ctx":"brumario","who":"Brumario"}]},{"text":"Soy Brumario, jefe del Equipo PP en el este.","uses":[{"file":"data/story.ts","line":893,"ctx":"brumario","who":"Brumario"}]},{"text":"El Cardenal Azul limpia el cielo y disipa la niebla. Si lo capturo, el país será nuestro: gris, quieto, sin viento.","uses":[{"file":"data/story.ts","line":893,"ctx":"brumario","who":"Brumario"}]},{"text":"Apartate de mi camino.","uses":[{"file":"data/story.ts","line":893,"ctx":"brumario","who":"Brumario"}]},{"text":"Un viento helado baja de las sierras.","uses":[{"file":"data/story.ts","line":899,"ctx":"brumario","who":""}]},{"text":"Una silueta enorme, con alas de tormenta, cruza el cielo.","uses":[{"file":"data/story.ts","line":899,"ctx":"brumario","who":""}]},{"text":"El Cardenal Azul se aleja hacia el sur. La niebla se disipa.","uses":[{"file":"data/story.ts","line":899,"ctx":"brumario","who":""}]},{"text":"Perdí. Pero esto no se termina acá.","uses":[{"file":"data/story.ts","line":900,"ctx":"brumario","who":"Brumario"}]},{"text":"Yo sólo respondo al Dr. Díaz. Él nunca se ensucia las manos.","uses":[{"file":"data/story.ts","line":900,"ctx":"brumario","who":"Brumario"}]},{"text":"Si querés seguir, la fábrica de Minas es el próximo paso. Garúa la dirige.","uses":[{"file":"data/story.ts","line":900,"ctx":"brumario","who":"Brumario"}]},{"text":"Tu celular vibra. Es un mensaje del Maestro Tabárez:","uses":[{"file":"data/story.ts","line":902,"ctx":"brumario","who":""}]},{"text":"\"Me enteré de todo, {player}. Es un logro enorme, pero esto recién empieza.","uses":[{"file":"data/story.ts","line":902,"ctx":"brumario","who":""}]},{"text":"Seguí hacia la costa de Rocha: en el faro de Cabo Polonio falta una lámpara.","uses":[{"file":"data/story.ts","line":902,"ctx":"brumario","who":""}]},{"text":"Y más adelante, en Minas, hay una fábrica abandonada que volvió a funcionar. Mirala con cuidado.\"","uses":[{"file":"data/story.ts","line":902,"ctx":"brumario","who":""}]},{"text":"Otro mensaje, un minuto después:","uses":[{"file":"data/story.ts","line":903,"ctx":"brumario","who":""}]},{"text":"\"Proyecto Pampero… ese nombre es mío. Fue un estudio que hice con Dr. Díaz para predecir el clima con ayuda de las criaturas.","uses":[{"file":"data/story.ts","line":903,"ctx":"brumario","who":""}]},{"text":"Se fue cuando me negué a venderlo. Si es él quien está detrás, esto también es cosa mía.","uses":[{"file":"data/story.ts","line":903,"ctx":"brumario","who":""}]},{"text":"Nuestro laboratorio era el viejo Observatorio del Cerro, en Piriápolis. Si podés, pasá a ver qué quedó ahí.\"","uses":[{"file":"data/story.ts","line":903,"ctx":"brumario","who":""}]},{"text":"{player}. Te estaba esperando en el camino.","uses":[{"file":"data/story.ts","line":908,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Pasé por la Quebrada de los Cuervos. Estaba vacía: ni un cuervo, ni un nido.","uses":[{"file":"data/story.ts","line":908,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Los datos que mandé al PP sirvieron para esto. Me usaron, y yo les creí.","uses":[{"file":"data/story.ts","line":908,"ctx":"rival_r5","who":"{rival}"}]},{"text":"No te pido perdón. Te pido un combate: necesito saber si todavía sirvo para algo.","uses":[{"file":"data/story.ts","line":908,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Bien jugado. Yo voy a hablar con mi tío.","uses":[{"file":"data/story.ts","line":911,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Nos vemos en el Centenario.","uses":[{"file":"data/story.ts","line":911,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Todavía te falta un poco. Entrená y seguí.","uses":[{"file":"data/story.ts","line":914,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Yo voy a hablar con mi tío.","uses":[{"file":"data/story.ts","line":914,"ctx":"rival_r5","who":"{rival}"}]},{"text":"{player}. Hablé con mi tío. Fue socio del Dr. Díaz y nunca me lo dijo.","uses":[{"file":"data/story.ts","line":922,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Ya no trabajo para nadie del PP: me di cuenta tarde de a quién le estaba creyendo.","uses":[{"file":"data/story.ts","line":922,"ctx":"rival_r24","who":"{rival}"}]},{"text":"No te pido ayuda, te pido que me veas pelear bien una vez. Falta Durazno y después la capital, y no pienso llegar segundo.","uses":[{"file":"data/story.ts","line":922,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Andá vos. Yo te sigo de cerca.","uses":[{"file":"data/story.ts","line":925,"ctx":"rival_r24","who":"{rival}"}]},{"text":"En el Centenario nos vemos las caras.","uses":[{"file":"data/story.ts","line":925,"ctx":"rival_r24","who":"{rival}"},{"file":"data/story.ts","line":928,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Esta vez gané yo, pero la capital es cosa tuya. Andá.","uses":[{"file":"data/story.ts","line":928,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Bienvenido a Mi Zoo. Es un parque con criaturas de todo el país, sueltas y a la vista.","uses":[{"file":"data/story.ts","line":935,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Se paga por tiempo de visita. Pasado ese tiempo suena una campana y los guardias te acompañan a la salida.","uses":[{"file":"data/story.ts","line":935,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Un minuto antes te vamos a avisar. No se devuelve el dinero si salís antes.","uses":[{"file":"data/story.ts","line":935,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Cuando quieras, acá estamos.","uses":[{"file":"data/story.ts","line":938,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"No te alcanza el dinero para esa entrada.","uses":[{"file":"data/story.ts","line":940,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Te damos 30 Safari Balls y 15 Galletas de Campaña. Con la galleta, la criatura se encariña y es más fácil de atrapar. Todo se devuelve al salir.","uses":[{"file":"data/story.ts","line":943,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Que disfrutes la visita.","uses":[{"file":"data/story.ts","line":943,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Gracias por la visita. Te acompaño a la salida.","uses":[{"file":"data/story.ts","line":952,"ctx":"safari_exit","who":"Guardia"}]},{"text":"No esperaba visitas. Soy Almada, fui alumno del Maestro Tabárez en este mismo observatorio.","uses":[{"file":"data/story.ts","line":966,"ctx":"almada","who":"Almada"}]},{"text":"Estudiábamos cómo el Pampero ordena el clima del Río de la Plata. Dr. Díaz y Tabárez dirigían el proyecto.","uses":[{"file":"data/story.ts","line":966,"ctx":"almada","who":"Almada"}]},{"text":"Cuando Tabárez se negó a vender los datos, Dr. Díaz se quedó con los instrumentos y yo me fui con él.","uses":[{"file":"data/story.ts","line":966,"ctx":"almada","who":"Almada"}]},{"text":"Pensé que íbamos a proteger el clima. Resulta que quería controlarlo.","uses":[{"file":"data/story.ts","line":966,"ctx":"almada","who":"Almada"}]},{"text":"Acá guardo el registro original. Si querés leerlo, ganame primero.","uses":[{"file":"data/story.ts","line":967,"ctx":"almada","who":"Almada"}]},{"text":"Tomá el registro. Está firmado por los dos: Tabárez y Dr. Díaz.","uses":[{"file":"data/story.ts","line":973,"ctx":"almada","who":"Almada"}]},{"text":"La última página la escribió Dr. Díaz: \"El Cardenal Azul tiene un ciclo. Si lo interrumpo, la niebla es mía para siempre\".","uses":[{"file":"data/story.ts","line":973,"ctx":"almada","who":"Almada"}]},{"text":"Por eso quiere capturarlo. No lo odia: lo necesita.","uses":[{"file":"data/story.ts","line":973,"ctx":"almada","who":"Almada"}]},{"text":"Dejo el Equipo PP. Voy a llevarle esto a Tabárez en persona.","uses":[{"file":"data/story.ts","line":974,"ctx":"almada","who":"Almada"}]},{"text":"Y esta MT era del observatorio: se usaba para medir los temblores del cerro.","uses":[{"file":"data/story.ts","line":974,"ctx":"almada","who":"Almada"}]},{"text":"Tu celular vibra. Es Facu:","uses":[{"file":"data/story.ts","line":977,"ctx":"almada","who":""}]},{"text":"\"Mi tío me contó que Almada fue su mejor alumno. Si lo convenciste de volver, ya hiciste más que yo.","uses":[{"file":"data/story.ts","line":977,"ctx":"almada","who":""}]},{"text":"No pienso quedarme atrás. Nos vemos en el camino.\"","uses":[{"file":"data/story.ts","line":977,"ctx":"almada","who":""}]},{"text":"Volvimos a vernos.","uses":[{"file":"data/story.ts","line":981,"ctx":"bruma2","who":"Bruma"}]},{"text":"Después del Anglo juré que no me ganarías otra vez.","uses":[{"file":"data/story.ts","line":981,"ctx":"bruma2","who":"Bruma"}]},{"text":"Esta torre emite la niebla que cubre Rivera. Mientras esté encendida, nadie ve lo que hacemos.","uses":[{"file":"data/story.ts","line":981,"ctx":"bruma2","who":"Bruma"}]},{"text":"La luz del transmisor se apaga.","uses":[{"file":"data/story.ts","line":987,"ctx":"bruma2","who":""}]},{"text":"Afuera, la niebla se disipa y el sol vuelve a la ciudad.","uses":[{"file":"data/story.ts","line":987,"ctx":"bruma2","who":""}]},{"text":"Perdí… otra vez.","uses":[{"file":"data/story.ts","line":988,"ctx":"bruma2","who":"Bruma"}]},{"text":"Dr. Díaz no se va a quedar en el norte. Dicen que prepara algo grande en Montevideo.","uses":[{"file":"data/story.ts","line":988,"ctx":"bruma2","who":"Bruma"}]},{"text":"Hacé lo que quieras. Brumario espera en la Quebrada de los Cuervos.","uses":[{"file":"data/story.ts","line":988,"ctx":"bruma2","who":"Bruma"}]},{"text":"Así que vos sos el entrenador que nos molesta.","uses":[{"file":"data/story.ts","line":994,"ctx":"garua2","who":"Garúa"}]},{"text":"Soy Garúa, comandante del Equipo PP.","uses":[{"file":"data/story.ts","line":994,"ctx":"garua2","who":"Garúa"}]},{"text":"La Represa mueve las torres: sin electricidad no hay niebla. Y yo controlo los interruptores.","uses":[{"file":"data/story.ts","line":994,"ctx":"garua2","who":"Garúa"}]},{"text":"Las turbinas vuelven a girar. En la ciudad, las luces se prenden una por una.","uses":[{"file":"data/story.ts","line":1000,"ctx":"garua2","who":""}]},{"text":"Perdí. Pero esto es solo una pieza: Dr. Díaz tiene otra torre en Rivera, y mucho más que eso.","uses":[{"file":"data/story.ts","line":1001,"ctx":"garua2","who":"Garúa"}]},{"text":"Yo vuelvo a mi fábrica de Minas. Si querés alcanzarme, tendrás que llegar hasta allá.","uses":[{"file":"data/story.ts","line":1001,"ctx":"garua2","who":"Garúa"}]},{"text":"Así que sos vos el que anda haciendo ruido en Fray Bentos.","uses":[{"file":"data/story.ts","line":1008,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Soy Bruma, administradora del Equipo PP.","uses":[{"file":"data/story.ts","line":1008,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Este frigorífico guarda las máquinas de niebla. Dr. Díaz las necesita funcionando.","uses":[{"file":"data/story.ts","line":1008,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Y vos tenés algo que él lleva años buscando: esa criatura que te acompaña guarda el eco del Cardenal Azul. Entregámela y nadie se lastima.","uses":[{"file":"data/story.ts","line":1008,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Perdí. Pero el proyecto es más grande que este frigorífico.","uses":[{"file":"data/story.ts","line":1012,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Dr. Díaz tiene torres y una represa, y yo no soy la única que sigue sus órdenes.","uses":[{"file":"data/story.ts","line":1012,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Entre las cosas de Bruma queda un objeto raro: un Repartir Exp, de los que el PP usaba para entrenar a su gente.","uses":[{"file":"data/story.ts","line":1014,"ctx":"bruma_anglo","who":""}]},{"text":"Tu celular vibra. Es el Maestro Tabárez:","uses":[{"file":"data/story.ts","line":1016,"ctx":"bruma_anglo","who":""}]},{"text":"\"{player}, tengo que decirte algo que callé demasiado tiempo.","uses":[{"file":"data/story.ts","line":1016,"ctx":"bruma_anglo","who":""}]},{"text":"Tu compañero nació en mi laboratorio durante el Proyecto Pampero. Guarda un eco del ciclo del viento, y por eso el PP te sigue.","uses":[{"file":"data/story.ts","line":1016,"ctx":"bruma_anglo","who":""}]},{"text":"Perdoname por no habértelo dicho en Carmelo. Cuidalo mucho.\"","uses":[{"file":"data/story.ts","line":1016,"ctx":"bruma_anglo","who":""}]},{"text":"Así que sos vos.","uses":[{"file":"data/story.ts","line":1022,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Soy Dr. Díaz, fundador del Proyecto Pampero. Lo que ustedes llaman Equipo PP.","uses":[{"file":"data/story.ts","line":1022,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Mi idea es simple: el clima es un recurso. Con las torres, la niebla se vende por días, por zonas, por contrato.","uses":[{"file":"data/story.ts","line":1022,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"El Pampero natural era un estorbo. Por eso quise capturarlo.","uses":[{"file":"data/story.ts","line":1022,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Tabárez nunca se animó a ir más lejos. Yo sí, y por eso hoy estoy acá.","uses":[{"file":"data/story.ts","line":1022,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Llegaste con las doce medallas. Se nota que no te asustan las torres.","uses":[{"file":"data/story.ts","line":1023,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Pero no vas a apagarme a mí.","uses":[{"file":"data/story.ts","line":1023,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Las últimas máquinas de niebla se apagan. Desde el puerto se ve el Río de la Plata, limpio, hasta el horizonte.","uses":[{"file":"data/story.ts","line":1029,"ctx":"calima","who":""}]},{"text":"Gané perdiendo… Ya no tengo equipo, ni dinero, ni torres.","uses":[{"file":"data/story.ts","line":1030,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Hacé lo que quieras. Pero el cielo nunca fue de nadie.","uses":[{"file":"data/story.ts","line":1030,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Tu celular vibra otra vez. Es el Maestro Tabárez:","uses":[{"file":"data/story.ts","line":1031,"ctx":"calima","who":""}]},{"text":"\"Lo lograron, {player}. El Equipo PP está disuelto.","uses":[{"file":"data/story.ts","line":1031,"ctx":"calima","who":""}]},{"text":"Con las doce medallas y el Equipo PP disuelto, la Liga te espera en el Estadio Centenario.","uses":[{"file":"data/story.ts","line":1031,"ctx":"calima","who":""}]},{"text":"Dr. Díaz fue mi colega y no supe verlo venir. Gracias por corregir lo que yo no pude.\"","uses":[{"file":"data/story.ts","line":1031,"ctx":"calima","who":""}]},{"text":"Al norte de la ciudad empieza la Ciclovía. Solo se entra en bicicleta. Usala desde el menú.","uses":[{"file":"data/story.ts","line":1045,"ctx":"gift_tac","who":"Dueña"}]},{"text":"Bienvenido a El Pedal. Hace veinte años que armo bicicletas para el norte.","uses":[{"file":"data/story.ts","line":1046,"ctx":"gift_tac","who":"Dueña"}]},{"text":"Esta quedó en el taller: era de mi hijo y ya no la usa. Llevatela, va cuatro veces más rápido que caminando.","uses":[{"file":"data/story.ts","line":1046,"ctx":"gift_tac","who":"Dueña"}]},{"text":"Se usa desde el menú. Bajo techo no se puede, y en combate no cambia nada.","uses":[{"file":"data/story.ts","line":1046,"ctx":"gift_tac","who":"Dueña"}]},{"text":"Al norte de la ciudad hay una Ciclovía. Solo se entra en bicicleta.","uses":[{"file":"data/story.ts","line":1050,"ctx":"gift_tac","who":"Dueña"}]},{"text":"Cada vez que bajo por la ciclovía me siento joven.","uses":[{"file":"data/story.ts","line":1054,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Llegaste hasta el final. Pocos lo hacen.","uses":[{"file":"data/story.ts","line":1055,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Eso se premia. Tomá, un mate bien fuerte para el camino.","uses":[{"file":"data/story.ts","line":1055,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Del otro lado de la plaza se compra más barato. Pero acá, el café es mejor.","uses":[{"file":"data/story.ts","line":1061,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"Compro de un lado y vendo del otro.","uses":[{"file":"data/story.ts","line":1062,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"Tomá, un regalo para el viaje. Que no se te acaben las Ultraballs.","uses":[{"file":"data/story.ts","line":1062,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"La represa es el orgullo de Salto. Y ahora, un problema.","uses":[{"file":"data/story.ts","line":1068,"ctx":"gift_sal","who":"Policía"}]},{"text":"Estoy de guardia, pero algo puedo hacer.","uses":[{"file":"data/story.ts","line":1069,"ctx":"gift_sal","who":"Policía"}]},{"text":"Tomá, que te sirve más que a mí.","uses":[{"file":"data/story.ts","line":1069,"ctx":"gift_sal","who":"Policía"}]},{"text":"El río siempre vuelve a su cauce.","uses":[{"file":"data/story.ts","line":1075,"ctx":"gift_pay","who":"Marinero"}]},{"text":"Hace años que navego esta costa.","uses":[{"file":"data/story.ts","line":1076,"ctx":"gift_pay","who":"Marinero"}]},{"text":"Llevate esto: no tiene mucho valor, pero sirve.","uses":[{"file":"data/story.ts","line":1076,"ctx":"gift_pay","who":"Marinero"}]},{"text":"El gimnasio de acá fue el más temido del litoral.","uses":[{"file":"data/story.ts","line":1082,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Mi abuelo me dijo que el frigorífico era cosa seria.","uses":[{"file":"data/story.ts","line":1083,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Tomá esto, para lo que venga.","uses":[{"file":"data/story.ts","line":1083,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Desde Carmelo que te vengo siguiendo.","uses":[{"file":"data/story.ts","line":1090,"ctx":"rival_final","who":"{rival}"}]},{"text":"Esta es mi revancha. Voy con todo.","uses":[{"file":"data/story.ts","line":1090,"ctx":"rival_final","who":"{rival}"}]},{"text":"Andá. El Campeón te espera arriba.","uses":[{"file":"data/story.ts","line":1093,"ctx":"rival_final","who":"{rival}"}]},{"text":"Y ganale. Si no, quedo mal yo también.","uses":[{"file":"data/story.ts","line":1093,"ctx":"rival_final","who":"{rival}"},{"file":"data/story.ts","line":1096,"ctx":"rival_final","who":"{rival}"}]},{"text":"Esta vez gané yo, pero el Campeón es otra cosa. Andá, te espera arriba.","uses":[{"file":"data/story.ts","line":1096,"ctx":"rival_final","who":"{rival}"}]},{"text":"Sos imparable. Volvé cuando quieras.","uses":[{"file":"data/story.ts","line":1113,"ctx":"champion","who":"Obdulio"}]},{"text":"Felicitaciones, {player}. Desde hoy sos el nuevo Campeón de la Liga Oriental.","uses":[{"file":"data/story.ts","line":1116,"ctx":"champion","who":"Obdulio"}]},{"text":"Tu nombre va a quedar en el Salón de la Fama del Centenario.","uses":[{"file":"data/story.ts","line":1116,"ctx":"champion","who":"Obdulio"}]},{"text":"Algunas semanas después, en Carmelo.","uses":[{"file":"data/story.ts","line":1124,"ctx":"champion","who":""}]},{"text":"Se habla de criaturas legendarias avistadas en el país:","uses":[{"file":"data/story.ts","line":1124,"ctx":"champion","who":""}]},{"text":"un viento helado en la Quebrada, un canto en la costa de Punta del Este.","uses":[{"file":"data/story.ts","line":1124,"ctx":"champion","who":""}]},{"text":"Tu aventura continúa.","uses":[{"file":"data/story.ts","line":1124,"ctx":"champion","who":""}]},{"text":"Ya respondiste. Pasá nomás.","uses":[{"file":"data/story.ts","line":1129,"ctx":"route_riddle","who":""}]},{"text":"No es eso. Pensalo y volvé a intentar.","uses":[{"file":"data/story.ts","line":1134,"ctx":"route_riddle","who":""}]},{"text":"Correcto. Se abre el paso.","uses":[{"file":"data/story.ts","line":1137,"ctx":"route_riddle","who":""}]},{"text":"La tranquera ya está abierta.","uses":[{"file":"data/story.ts","line":1143,"ctx":"route_palanca","who":""}]},{"text":"Soltaste la palanca. Los cerrojos vuelven a su lugar.","uses":[{"file":"data/story.ts","line":1145,"ctx":"route_palanca","who":""}]},{"text":"Se oye el último cerrojo. La tranquera se abre sola.","uses":[{"file":"data/story.ts","line":1152,"ctx":"route_palanca","who":""}]},{"text":"Algo hizo un ruido seco. Los cerrojos volvieron a su lugar.","uses":[{"file":"data/story.ts","line":1158,"ctx":"route_palanca","who":""}]},{"text":"PS","uses":[{"file":"game/battle-scene.ts","line":272,"ctx":"box","who":""},{"file":"game/menus.ts","line":30,"ctx":"hpBar","who":""},{"file":"game/menus.ts","line":244,"ctx":"render","who":""}]},{"text":"¡No te quedan criaturas en condiciones de pelear!","uses":[{"file":"game/battle-scene.ts","line":417,"ctx":"runBattle","who":""}]},{"text":"…","uses":[{"file":"game/battle-scene.ts","line":417,"ctx":"runBattle","who":""},{"file":"game/world.ts","line":910,"ctx":"blackout","who":""}]},{"text":"Todo se pone gris…","uses":[{"file":"game/battle-scene.ts","line":417,"ctx":"runBattle","who":""}]},{"text":"Movimiento nuevo","uses":[{"file":"game/battle-scene.ts","line":589,"ctx":"chooseMove","who":""}]},{"text":"Poder","uses":[{"file":"game/battle-scene.ts","line":614,"ctx":"show","who":""}]},{"text":"Precisión","uses":[{"file":"game/battle-scene.ts","line":615,"ctx":"show","who":""}]},{"text":"¿Cuál movimiento debería olvidar?","uses":[{"file":"game/battle-scene.ts","line":984,"ctx":"learnFlow","who":""}]},{"text":"▶▶","uses":[{"file":"game/hud.ts","line":37,"ctx":"mountHud","who":""}]},{"text":"x2","uses":[{"file":"game/hud.ts","line":37,"ctx":"mountHud","who":""}]},{"text":"El hornero no te obedece todavía. Hace falta la Medalla Florida.","uses":[{"file":"game/menus.ts","line":103,"ctx":"pickFlight","who":""}]},{"text":"Acá adentro no se puede usar.","uses":[{"file":"game/menus.ts","line":104,"ctx":"pickFlight","who":""}]},{"text":"Todavía no conocés ninguna ciudad adonde volar.","uses":[{"file":"game/menus.ts","line":106,"ctx":"pickFlight","who":""}]},{"text":"Ataques","uses":[{"file":"game/menus.ts","line":249,"ctx":"render","who":""}]},{"text":"Mochila","uses":[{"file":"game/menus.ts","line":306,"ctx":"openBag","who":""}]},{"text":"¡No es momento de usar eso!","uses":[{"file":"game/menus.ts","line":335,"ctx":"use","who":""},{"file":"game/menus.ts","line":340,"ctx":"use","who":""}]},{"text":"¡No hay lugar para más criaturas!","uses":[{"file":"game/menus.ts","line":337,"ctx":"use","who":""}]},{"text":"Se equipa fuera de combate.","uses":[{"file":"game/menus.ts","line":341,"ctx":"use","who":""}]},{"text":"Mejor usala fuera de combate.","uses":[{"file":"game/menus.ts","line":342,"ctx":"use","who":""},{"file":"game/menus.ts","line":343,"ctx":"use","who":""}]},{"text":"No tendría ningún efecto.","uses":[{"file":"game/menus.ts","line":357,"ctx":"use","who":""},{"file":"game/menus.ts","line":417,"ctx":"onUse","who":""},{"file":"game/menus.ts","line":439,"ctx":"useInField","who":""}]},{"text":"¡Eso es muy importante para tirarlo!","uses":[{"file":"game/menus.ts","line":362,"ctx":"use","who":""}]},{"text":"¡Las Pokeballs se usan en combate!","uses":[{"file":"game/menus.ts","line":402,"ctx":"useInField","who":""}]},{"text":"Solo se puede usar en combate.","uses":[{"file":"game/menus.ts","line":409,"ctx":"useInField","who":""}]},{"text":"PokeDex","uses":[{"file":"game/menus.ts","line":476,"ctx":"openDex","who":""},{"file":"game/menus.ts","line":753,"ctx":"openCard","who":""}]},{"text":"Ninguna criatura coincide con la búsqueda.","uses":[{"file":"game/menus.ts","line":483,"ctx":"show","who":""}]},{"text":"Sin datos. Todavía no viste a esta criatura.","uses":[{"file":"game/menus.ts","line":489,"ctx":"show","who":""}]},{"text":"Departamento","uses":[{"file":"game/menus.ts","line":675,"ctx":"openMap","who":""}]},{"text":"Zona","uses":[{"file":"game/menus.ts","line":676,"ctx":"openMap","who":""}]},{"text":"Criaturas que aparecen","uses":[{"file":"game/menus.ts","line":677,"ctx":"openMap","who":""}]},{"text":"Mapa","uses":[{"file":"game/menus.ts","line":681,"ctx":"openMap","who":""}]},{"text":"???","uses":[{"file":"game/menus.ts","line":707,"ctx":"show","who":""},{"file":"game/menus.ts","line":709,"ctx":"show","who":""}]},{"text":"Ninguna","uses":[{"file":"game/menus.ts","line":709,"ctx":"show","who":""}]},{"text":"Ficha de Entrenador","uses":[{"file":"game/menus.ts","line":748,"ctx":"openCard","who":""}]},{"text":"Nombre","uses":[{"file":"game/menus.ts","line":751,"ctx":"openCard","who":""}]},{"text":"Dinero","uses":[{"file":"game/menus.ts","line":752,"ctx":"openCard","who":""}]},{"text":"Tiempo","uses":[{"file":"game/menus.ts","line":754,"ctx":"openCard","who":""}]},{"text":"Victorias","uses":[{"file":"game/menus.ts","line":755,"ctx":"openCard","who":""}]},{"text":"Inicio","uses":[{"file":"game/menus.ts","line":756,"ctx":"openCard","who":""}]},{"text":"Medallas","uses":[{"file":"game/menus.ts","line":760,"ctx":"openCard","who":""}]},{"text":"★ Campeón de la Liga Oriental ★","uses":[{"file":"game/menus.ts","line":762,"ctx":"openCard","who":""}]},{"text":"Opciones","uses":[{"file":"game/menus.ts","line":788,"ctx":"openOptions","who":""}]},{"text":"Controles","uses":[{"file":"game/menus.ts","line":826,"ctx":"openControls","who":""}]},{"text":"¿En qué ranura querés guardar?","uses":[{"file":"game/menus.ts","line":843,"ctx":"openSave","who":""}]},{"text":"No se pudo guardar.","uses":[{"file":"game/menus.ts","line":858,"ctx":"openSave","who":""}]},{"text":"¿Algo más?","uses":[{"file":"game/menus.ts","line":871,"ctx":"openShop","who":"Almacenero"}]},{"text":"¡Gracias! ¡Volvé pronto!","uses":[{"file":"game/menus.ts","line":873,"ctx":"openShop","who":"Almacenero"}]},{"text":"↑↓ ±1 · ←→ ±10","uses":[{"file":"game/menus.ts","line":883,"ctx":"qtyPicker","who":""}]},{"text":"No te alcanza la plata.","uses":[{"file":"game/menus.ts","line":907,"ctx":"buyFlow","who":"Almacenero"},{"file":"game/menus.ts","line":911,"ctx":"buyFlow","who":""}]},{"text":"¡Acá tenés! Gracias.","uses":[{"file":"game/menus.ts","line":914,"ctx":"buyFlow","who":"Almacenero"}]},{"text":"Por comprar 10, te regalo una Superball.","uses":[{"file":"game/menus.ts","line":917,"ctx":"buyFlow","who":"Almacenero"}]},{"text":"No tenés nada para vender.","uses":[{"file":"game/menus.ts","line":926,"ctx":"sellFlow","who":"Almacenero"}]},{"text":"Encendiste la computadora. Se conectó a la Caja de Criaturas.","uses":[{"file":"game/menus.ts","line":955,"ctx":"openPC","who":""}]},{"text":"La Caja está vacía.","uses":[{"file":"game/menus.ts","line":960,"ctx":"openPC","who":""}]},{"text":"Tu equipo está lleno.","uses":[{"file":"game/menus.ts","line":961,"ctx":"openPC","who":""}]},{"text":"¡No podés quedarte sin criaturas!","uses":[{"file":"game/menus.ts","line":969,"ctx":"openPC","who":""}]},{"text":"Necesitás al menos una criatura sana en el equipo.","uses":[{"file":"game/menus.ts","line":973,"ctx":"openPC","who":""}]},{"text":"Bienvenido al mundo de Poke Uruguay.","uses":[{"file":"game/scenes.ts","line":306,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Soy el Maestro Tabárez. Dirigí a la selección durante años y hoy me dedico a estudiar a las criaturas de este país.","uses":[{"file":"game/scenes.ts","line":306,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"En este país conviven personas y criaturas.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Algunas nadan en el Río de la Plata, otras recorren las praderas o vuelan sobre las sierras.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"La gente trabaja con ellas, las entrena y, a veces, combate con ellas.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Ahora hablemos de vos. ¿Cómo te presentás?","uses":[{"file":"game/scenes.ts","line":312,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Así que te llamás {player}. Un gusto.","uses":[{"file":"game/scenes.ts","line":319,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Este es mi nieto. Compite con vos desde que eran niños. ¿Cómo se llamaba?","uses":[{"file":"game/scenes.ts","line":320,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Claro, {rival}. Cómo me pude olvidar.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"{player}, tu propia historia está por empezar.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Un camino largo te espera por todo el Uruguay. Vamos.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"★ Campeón","uses":[{"file":"game/scenes.ts","line":429,"ctx":"slotCard","who":""}]},{"text":"Tu equipo","uses":[{"file":"game/sidebar.ts","line":76,"ctx":"mountSidebar","who":""}]},{"text":"▾","uses":[{"file":"game/sidebar.ts","line":76,"ctx":"mountSidebar","who":""}]},{"text":"▼","uses":[{"file":"game/ui.ts","line":39,"ctx":"mountUI","who":""}]},{"text":"Listo","uses":[{"file":"game/ui.ts","line":199,"ctx":"textInput","who":""}]},{"text":"¡Ding, dong! Se terminó el tiempo del concurso.","uses":[{"file":"game/world.ts","line":215,"ctx":"safariClock","who":""}]},{"text":"Los guardaparques te acompañan de vuelta con los jueces.","uses":[{"file":"game/world.ts","line":215,"ctx":"safariClock","who":""}]},{"text":"¡Ding, dong! Se terminó el tiempo contratado.","uses":[{"file":"game/world.ts","line":216,"ctx":"safariClock","who":""}]},{"text":"Los guardias del Safari te acompañan hasta la salida.","uses":[{"file":"game/world.ts","line":216,"ctx":"safariClock","who":""}]},{"text":"El efecto del Repelente se terminó.","uses":[{"file":"game/world.ts","line":531,"ctx":"onStep","who":""}]},{"text":"Un mojón de la ruta, con el kilómetro pintado en rojo.","uses":[{"file":"game/world.ts","line":687,"ctx":"interact","who":""}]},{"text":"Quien pasa a su lado queda anotado en el punto de control: si las criaturas caen, se despierta acá con la salud completa.","uses":[{"file":"game/world.ts","line":687,"ctx":"interact","who":""}]},{"text":"No se puede curar a nadie en este lugar. Para eso hace falta una Policlínica.","uses":[{"file":"game/world.ts","line":687,"ctx":"interact","who":""}]},{"text":"Un zarzal espeso y espinoso. Con algo filoso se podría abrir paso.","uses":[{"file":"game/world.ts","line":793,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. Para usar el Machete hace falta la Medalla de Fray Bentos.","uses":[{"file":"game/world.ts","line":794,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. El Machete no alcanza todavía: hace falta la Medalla Salto.","uses":[{"file":"game/world.ts","line":795,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. Con el Machete se puede abrir paso.","uses":[{"file":"game/world.ts","line":796,"ctx":"cutBush","who":""}]},{"text":"¡Despejaste el camino!","uses":[{"file":"game/world.ts","line":802,"ctx":"cutBush","who":""}]},{"text":"El agua está turbia. Sin una caña, mejor no meterse.","uses":[{"file":"game/world.ts","line":853,"ctx":"fish","who":""}]},{"text":"Tus criaturas están debilitadas. Mejor no arriesgarse.","uses":[{"file":"game/world.ts","line":855,"ctx":"fish","who":""}]},{"text":"Se terminó el tiempo del concurso. Llevale tu mejor pez al juez.","uses":[{"file":"game/world.ts","line":857,"ctx":"fish","who":""}]},{"text":"Lanzaste la caña al agua…","uses":[{"file":"game/world.ts","line":864,"ctx":"fish","who":""}]},{"text":"No picó nada. Probá de nuevo.","uses":[{"file":"game/world.ts","line":871,"ctx":"fish","who":""}]},{"text":"¡Algo picó!","uses":[{"file":"game/world.ts","line":876,"ctx":"fish","who":""}]},{"text":"Llegó tarde: se acabó el tiempo y la línea quedó floja.","uses":[{"file":"game/world.ts","line":884,"ctx":"fish","who":""}]},{"text":"Volviste a descansar para recuperarte.","uses":[{"file":"game/world.ts","line":929,"ctx":"runScript","who":""}]},{"text":"Necesitás otra criatura en condiciones para seguir viaje.","uses":[{"file":"game/world.ts","line":983,"ctx":"tradeCreature","who":""},{"file":"game/world.ts","line":999,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1003,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1055,"ctx":"criadero","who":""},{"file":"game/world.ts","line":1059,"ctx":"criadero","who":""}]},{"text":"Bienvenido a la guardería. Cuido a tus criaturas mientras caminás: ganan experiencia con cada paso que das.","uses":[{"file":"game/world.ts","line":997,"ctx":"daycare","who":""}]},{"text":"Dejala y volvé cuando quieras. Retirarla cuesta un poco más cuanto más haya crecido.","uses":[{"file":"game/world.ts","line":997,"ctx":"daycare","who":""}]},{"text":"Tu equipo está completo. Dejá lugar y volvé a buscarla.","uses":[{"file":"game/world.ts","line":1017,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1073,"ctx":"criadero","who":""}]},{"text":"Bienvenido al Criadero Los Teros. Acá las criaturas crecen con aire libre y buen pasto.","uses":[{"file":"game/world.ts","line":1047,"ctx":"criadero","who":""}]},{"text":"Cuando quieras. Acá las cuidamos bien.","uses":[{"file":"game/world.ts","line":1052,"ctx":"criadero","who":""}]},{"text":"Los corrales están llenos. Retirá a alguna primero.","uses":[{"file":"game/world.ts","line":1054,"ctx":"criadero","who":""}]}];
